    if(on){const cz=(V[0].p[2]+V[1].p[2]+V[2].p[2])/3,cu=(V[0].q[0]+V[1].q[0]+V[2].q[0])/3,cy=(V[0].q[1]+V[1].q[1]+V[2].q[1])/3;on=Math.sign(cz)===s&&Math.abs(Math.abs(cz)-HDK.sideZ(cu,cy))<tol;}
