      const prof=[[uD+.04,yw],[uD+.22,yt-.01],[uE-.12,yt],[uE-.05,yt-.012-hood*.3],[uE-.02,yt-.06],[uE-.015,.92+dy],[uE-.05-.06*stack,.8+dy],[uE-.1+.18*stack,.66+dy],[uE-.18+.14*stack,yF+.12]];
