  const topCore=E.layout==='V8'?.4:.47;let hm=9;for(let u=trans?uc-.35:uc-hx;u<=(trans?uc+.32:uc+hx+.1);u+=.05)hm=Math.min(hm,topY(u,.22));
  const yC=Math.max(yFloor+.12,Math.min(D.arch.cy+.2,hm-topCore-.03));
