      hdTube(mb,[[c[0]+.055,c[1]+.11,c[2]+.04],[c[0]+.1,c[1]+.14,c[2]+.08],[c[0]+.2,c[1]+.08,c[2]+.12]],.008,8,SMC('#b01e18',SM.HOSE),false,true);
