    hdBumperPocket(out,bar,rim,.03,HC.GB,HC.REFLC,.9);const c=bar.onBar(s*(ind[0]+ind[1])/2,Y(.299),.02);
    hdPart(out,mb=>{ball(mb,c,.0065,12,HC.BULB);},50);
