/* =====================================================================================
   THE HATCH GROUP B'S CABIN (Studio 2): the Hatch's finished Studio 2 cabin in its rally trim (cars/hatch 94
   htCabin2 with o.rally: the floor and the roof's inside painted, no rear seats or parcel shelf, the buckets low), the
   cage the Studio's has (cars/coupe-gt 85 cgCage), and what a Group B car carries:
   - a harness bar across the main hoop and a four-point harness in red on each bucket: the shoulder straps from the
     bar over the seat's back, the lap straps from the floor, the round buckle;
   - the co-driver's trip meter on the dash's right, its two counters, the map lamp on its gooseneck, the intercom's
     box under the dash;
   - the master cut-off's red knob on the dash's middle, the extinguisher on the floor between the seats;
   - the spare wheel strapped flat in the back, on the boot's floor.
   ===================================================================================== */
function hbCabin2(out,car){
  const K=HDK,D=K.D,G=D.G,X=K.X,dy=D.dy,pil=G.pillars.map(p=>p[0]),C=htCabin2(out,car,{rally:1}),{yF,cy}=C,uh=pil[0]+.08;
  cgCage(out,car,{uh,inset:.07,r:.02,floorY:.3+dy});
  const WEB=SMC('#c41e1a',SM.CLOTH),ALU=SMC('#b9bcc1',SM.BRUSH),BLK=C.BLK,CAGE=SMC('#2c2d30',SM.SATIN);
  /* ---------- the harness bar, the harnesses ---------- */
  const hb=yF+.66,zb=K.sideZ(uh,hb)-.07;hdPart(out,mb=>{hdTube(mb,[[X(uh),hb,-zb],[X(uh),hb,zb]],.018,14,CAGE,false,true);},40);
  const W=(pts,w=.022)=>hdPart(out,mb=>{hdSweep(mb,suvPath(pts,4,2),[[-w,-.0015],[w,-.0015],[w,.0015],[-w,.0015]],WEB,[0,0,1],true,true);},40);
  for(const s of [1,-1]){const c=[X(pil[0]-.3),yF+.12,s*.36],M=M4T(c[0],c[1],c[2]),Mb=M4.mul(M,M4RZ(.3)),at=p=>M4.xform(Mb,p),bk=M4.xform(M,[.2,.13,0]);
    for(const e of [-1,1]){W([[X(uh)+.02,hb+.018,c[2]+e*.07],at([-.11,.68,e*.06]),at([.02,.62,e*.06]),at([.03,.36,e*.055]),at([.04,.14,e*.045]),V3.add(bk,[-.03,0,e*.02])]);
      hdPart(out,mb=>{hdRBox(mb,at([.035,.42,e*.055]),[.004,.022,.028],.003,ALU,2);},30);
      const fl=[c[0]-.02,cy(pil[0]-.28,c[2]+e*.24)+.004,c[2]+e*.24];W([fl,M4.xform(M,[.0,.12,e*.2]),M4.xform(M,[.1,.13,e*.12]),V3.add(bk,[0,0,e*.03])]);
      hdPart(out,mb=>{hdRBox(mb,V3.add(fl,[0,.01,0]),[.02,.01,.018],.004,ALU,2);cpHex(mb,V3.add(fl,[0,.02,0]),[0,1,0],.007,.005);},30);}
    hdPart(out,mb=>{hdCyl(mb,V3.add(bk,[0,-.004,0]),V3.add(bk,[0,.012,0]),.04,.038,28,ALU);hdCyl(mb,V3.add(bk,[0,.012,0]),V3.add(bk,[0,.019,0]),.028,.025,24,SMC('#1a1a1c',SM.PLASTIC));},40);}
  /* ---------- the co-driver's trip meter, the map lamp, the intercom ---------- */
  {const u=G.cowl+.44,y=D.belt(u)-.02,z=.38,c=[X(u),y,z];
    hdPart(out,mb=>{hdRBox(mb,V3.add(c,[0,.035,0]),[.03,.035,.075],.008,BLK,3);for(const dz of [-.035,.035]){hdRBox(mb,V3.add(c,[-.031,.045,dz]),[.002,.014,.03],.002,SMC('#0d0d0e',SM.PLASTIC),1);
        for(let k=0;k<5;k++)hdRBox(mb,V3.add(c,[-.0325,.045,dz-.022+k*.011]),[.0006,.009,.004],.0004,SMC('#e8e6df',MAT.COL,.2),1);}
      for(const dz of [-.05,-.02,.02,.05])hdCyl(mb,V3.add(c,[-.031,.015,dz]),V3.add(c,[-.04,.015,dz]),.005,.005,10,ALU);},35);
    hdPart(out,mb=>{const a=V3.add(c,[.0,.07,.08]),pts=[a,V3.add(a,[-.02,.08,.02]),V3.add(a,[-.07,.12,-.02]),V3.add(a,[-.11,.1,-.04])];hdTube(mb,suvPath(pts,4,2),.004,8,BLK,false,true);
      const h=pts[3];hdCyl(mb,h,V3.add(h,[-.02,-.025,-.004]),.014,.018,14,BLK);hdCyl(mb,V3.add(h,[-.02,-.025,-.004]),V3.add(h,[-.021,-.027,-.004]),.017,.017,14,SMC('#fff3c0',MAT.COL,.6));},35);
    hdPart(out,mb=>{const b=[X(G.cowl+.3),yF+.28,.25];hdRBox(mb,b,[.05,.025,.06],.006,BLK,2);for(const dz of [-.03,.03])hdCyl(mb,V3.add(b,[-.05,0,dz]),V3.add(b,[-.06,0,dz]),.008,.008,12,ALU);},30);}
  /* ---------- the master cut-off on the dash's middle, the extinguisher between the seats ---------- */
  {const u=G.cowl+.46,x=X(u),y=D.belt(u)-.17;hdPart(out,mb=>{const p=[x,y,.03];hdRBox(mb,p,[.004,.025,.025],.004,SMC('#d6b21a',SM.PLASTIC),2);hdCyl(mb,V3.add(p,[-.004,0,0]),V3.add(p,[-.024,0,0]),.016,.014,18,SMC('#c41e1a',SM.PLASTIC));
      hdRBox(mb,V3.add(p,[-.03,0,0]),[.006,.004,.016],.003,SMC('#c41e1a',SM.PLASTIC),1);},35);}
  {const z=0,u0=pil[0]-.05,u1=pil[0]-.35,rr=.05,y=cy((u0+u1)/2,z)+rr+.012,A=[X(u0),y,z],B=[X(u1),y,z];
    hdPart(out,mb=>{cpRev(mb,A,B,[[0,0],[rr*.6,0],[rr,.03],[rr,.26],[rr*.7,.29],[.016,.3]],SMC('#c41e1a',SM.PAINTED),28,40);},40);
    hdPart(out,mb=>{hdCyl(mb,B,V3.add(B,[.03,0,0]),.016,.014,14,MM.CHROME);hdRBox(mb,V3.add(B,[.045,.02,0]),[.018,.007,.011],.004,BLK,2);
      for(const u of [u0-.07,u1+.08]){const ring=[];for(let k=0;k<=24;k++){const a=k/24*TAU;ring.push([X(u),y+Math.sin(a)*(rr+.004),z+Math.cos(a)*(rr+.004)]);}hdTube(mb,ring,.005,6,ALU,true,false);}},40);}
  /* ---------- the spare wheel strapped flat on the boot's floor ---------- */
  {const u=(G.rr+G.be)/2-.02,yB=cy(u,0),sw={R:.29,W:.19,rim:15},sp=new MB();hdTyre(sp,sw,{kind:'at'});const rr2=hdRimParts(sp,sw,{face:.03,lugs:4,barrel:SMC('#ece9e2',SM.PAINTED),lip:SMC('#ece9e2',SM.PAINTED)});
    hdPart(sp,mb=>{hdRev(mb,[[0,.026],[.06,.026],[.075,.03]],48,SMC('#ece9e2',SM.PAINTED),0,TAU,true);},30);
    xformMB(sp,M4.mul(M4T(X(u),yB+sw.W/2+.004,0),M4RX(-PI/2)));hdPut(out,sp);
    hdPart(out,mb=>{for(const dz of [-.12,.12]){const pts=[[X(u+.3),yB+.004,dz],[X(u+.28),yB+sw.W+.01,dz],[X(u-.28),yB+sw.W+.01,dz],[X(u-.3),yB+.004,dz]];hdSweep(mb,pts,[[-.0015,-.02],[.0015,-.02],[.0015,.02],[-.0015,.02]],SMC('#1a1a1c',SM.CLOTH),[0,0,1],true,true);
      hdRBox(mb,[X(u),yB+sw.W+.012,dz],[.025,.006,.024],.003,ALU,1);}},30);}
}

;
/* =====================================================================================
   THE HATCH GROUP B'S STUDIO 2 (KIT.setAlt('2') picks HD_CARS.hatchB2 for the build 'hatchB'): its Studio car (80 to
   86 here) with the rest of it built again on the Hatch's Studio 2 kit (cars/hatch 90 to 94) and its own (95):
   - the underside, whole, raised with the body for gravel: the Hatch's, with its struts in red springs and gold
     dampers out at the wider track, aluminium guards under the sump, the gearbox and the subframe (behind the stone
     guard, 82) and under the tank, a straight pipe in place of the centre box;
   - its own engine bay: the four on a big turbo with anti-lag (its air valve and plumbing), its air from a duct at
     the cowl in place of the airbox, a strut brace across the towers, no pad under the bonnet;
   - a rally car's bits in place of the road car's: the red tow straps front and back, the master cut-off's pull at
     the windscreen's foot, the side repeaters, the fuel flap, the aerial, the glass's seals, the washer jets; no plate
     (its number panels are 86's);
   - the cabin in rally trim, caged, the buckets in red harnesses, the co-driver's trip meter and map lamp, the
     extinguisher, the spare in the back (95); the spot lamps on the bonnet, lifting with it; deeper wheel houses.
   ===================================================================================== */
HD_CARS.hatchB2={
  skip:HD_CARS.hatchB.skip,
  noGame:{under:1,exhaust:1},
  build(out){
    const b=out.b,lk=b.look,G=out.D.G;
    const W=hbWheel(lk.tyre);out.wheel=out.wheelR=W.spin;out.brake=out.brakeR=W.fixed;
    {const ar=new MB();hdArches(ar,out,{zi:[.5,.5]});cgDropFlare(out);out.hd.arches=ar;}
    {const fl=new MB();hdFlares(fl);cgFlareBolts(fl,out);out.hd.flares=fl;}
    {const f=new MB();htFace(f,out);hbFront(f,out);out.hd.face=f;}
    {const t=new MB();htTail(t,out);out.hd.tail=t;}
    /* (the spot lamps on the bonnet, so they lift with it) */
    {const h=new MB();hbHoodPlate(h,out);htHoodBits(h,out);hbSpots(h,out);out.hd.hood=h;}
    {const c=new MB();hbCabin2(c,out);out.hd.cabin=c;}
    {const t=new MB();hdMirrors(t,out);hdHandles(t,out);hdWipers(t,out,{rear:1,blades:[[-.56,.04,-.44],[.0,.56,.08]]});
      cgRoofScoop(t,G.rf+.08,G.rf+.5,.17,.075);hbWing(t,out);hbLouvres(t,out);hbPanels(t,out);hbFlaps(t,out);out.hd.trim=t;}
    {const x=new MB();htExtras2(x,out,{noPlate:1,noBadges:1,rally:1});out.hd.extras=x;}
    out.bay=htBay2(out,{engine:{block:'#85888d',head:'#9a9da2',cover:'#b0201c',leads:'#b0201c',turbo:'big',antilag:1,ram:1},brace:1,noPad:1});
    out.under=htUnder2(out,{skids:1,skidU0:.66,exhaust:'straight',spring:'#c8241c',damper:'#d6a51a'});
  },
  views:HD_CARS.hatchB.views
};

;
/* =====================================================================================
   THE HYPERCAR IN THE STUDIO: the game's own mid-engine V10 (36_hyper BODIES.hyper, the Stock build in
   37_newbuilds: "Nothing in town is faster"), built finer, with each part modelled again in this folder, one file a
   part: 81 the wheel, 82 the face (lamps, intakes, the slot, the bonnet's vents, the flank intakes), 83 the tail
   (the light blades, the mesh panel, the two fat tips, the diffuser), 84 the bolt-ons and the engine cover's
   louvres, 85 the cabin, 86 the V10 behind the cabin and the bay round it, 87 the front trunk (79_bay's
   mid-engine layout). What the game paints on as decals or builds as plain boxes and this folder builds again is
   left off the game's body (skip); the game's own pipes and tips, which nothing skips, are taken off its body
   here and built again. The Track edition (../hyper-track) is built by the same hpBuild with its own parts added.
   ===================================================================================== */
HD_CARS.hyper={
  skip:{FACES:['hyper'],TAILS:['hyper'],FRONTS:['lip'],REARS:['coupeDiff']},
  build(out){hpBuild(out,{});},
  views:{cabin:D=>{const G=D.G,u=G.rr-.05;return {p:[D.X(u),D.belt(u)+.36,1.75],t:[D.X(G.cowl+.5),D.belt(u)-.25,-.25]};}}
};
/* the build, shared with the Track: o {wheel (a function of the tyre), track (the Track's parts), short (the flank
   intakes shortened by this much, clear of the flares)} */
function hpBuild(out,o){
  const b=out.b,lk=b.look;
  const W=(o.wheel||hpWheel)(lk.tyre);out.wheel=out.wheelR=W.spin;out.brake=out.brakeR=W.fixed;
  /* (with flares, the widebody's way: the fender's own skin kept, the game's flare taken off out to its full stand-off) */
  const ar=new MB();hdArches(ar,out,lk.flares?{skin:1}:{});out.hd.arches=ar;
  if(lk.flares){const fl=new MB();hdFlares(fl);out.hd.flares=fl;}
  {const f=new MB(),h=new MB();hpFace(f,out,o);hpHoodVents(h,out);out.hd.face=f;out.hd.hood=h;}
  {const t=new MB();hpTail(t,out);out.hd.tail=t;}
  {const c=new MB();hpCabin(c,out);out.hd.cabin=c;}
  {const t=new MB();hdMirrorsRace(t,out);hpHandles(t,out);hdWipers(t,out);hpCover(t,out);out.hd.trim=t;}
  {const e=new MB();hpEngine(e,out);out.hd.engine=e;}
  if(o.track)o.track(out);
  out.bay=hpBay(out);
  out.under=hdUnder(out);
}
/* where a line a + t d meets a convex outline P (2D): [t0, t1], or null */
function hpClip(P,a,d){let t0=-1e9,t1=1e9;const w=hdCCW(P);
  for(let i=0;i<P.length;i++){const p=P[i],q=P[(i+1)%P.length],n=[-(q[1]-p[1])*w,(q[0]-p[0])*w],num=(a[0]-p[0])*n[0]+(a[1]-p[1])*n[1],den=d[0]*n[0]+d[1]*n[1];
    if(Math.abs(den)<1e-12){if(num<0)return null;continue;}const t=-num/den;if(den>0)t0=Math.max(t0,t);else t1=Math.min(t1,t);}
  return t1>t0?[t0,t1]:null;}
/* a woven mesh across a convex outline P (2D): bars on the two diagonals every pc metres, each from at(p2, lift) */
function hpMesh(mb,P,pc,r,m,at){const c=hdCen(P);
  for(const d of [[Math.SQRT1_2,Math.SQRT1_2],[Math.SQRT1_2,-Math.SQRT1_2]]){const n=[-d[1],d[0]];
    for(let k=-60;k<=60;k++){const a=[c[0]+n[0]*k*pc,c[1]+n[1]*k*pc],T=hpClip(P,a,d);if(!T||T[1]-T[0]<.01)continue;
      const path=[];const ns=Math.max(1,Math.ceil((T[1]-T[0])/.03));for(let i=0;i<=ns;i++){const t=T[0]+(T[1]-T[0])*i/ns;path.push(at([a[0]+d[0]*t,a[1]+d[1]*t],d[0]>0===d[1]>0?0:r*1.6));}
      hdTube(mb,path,r,4,m,false,false);}}}

;
/* =====================================================================================
   THE HYPERCAR'S WHEEL: its 305/30R20 performance tyre on the 20-inch forged wheel the game gives it (30_wheels
   'split', in the build's dark grey), with the game's race brake behind it, modelled for a close look. Same axes
   and size as the game's wheel.
   - The tyre (78_run hdTyre 'perf').
   - The wheel: five forged Y spokes, each one spoke at the hub splitting into two as it runs out to the lip, rounded
     across, its face falling in a deep concave sweep from the lip to the hub; a machined edge along each spoke's
     face; the hub's flat with five nuts, a plain cap; the barrel deep behind the spokes; the lip's face machined.
   - The brake (78_run hdBrake): the big ventilated rotor and a six-piston caliper in the build's yellow.
   ===================================================================================== */
function hpWheel(w){
  const spin=new MB(),fixed=new MB();hdTyre(spin,w,{kind:'perf'});
  const rimR=w.rim*.0254/2,hw=w.W/2,zo=hw*.77,RIMM=SV([1,1,1],MAT.RIM),CUT=SMC('#6d7076',SM.BRUSH),face=zo-.064,r0=.072,r1=rimR-.008;
  /* the concave fall from the lip to the hub */
  const fz=r=>face+.012+(zo-.002-face-.012)*Math.pow(clamp((r-r0)/(r1-r0),0,1),.75);
  hdRimParts(spin,w,{lugs:5,pcd:.112,face:face+.01,lip:RIMM,barrel:HC.CAST,lugR:.0105,lugH:.022,lugA:PI/5,valveA:0});
  /* the spokes: five, each splitting into two from a third of the way out */
  for(let k=0;k<5;k++)for(const e of [-1,1]){const am=k/5*TAU,n=16,rings=[],edge=[];
    for(let i=0;i<=n;i++){const t=i/n,r=r0+(r1-r0)*t,sp=Math.max(0,t-.22)/.78,a=am+e*(.018+.15*Math.pow(sp,1.15)),w2=.0128-.0045*t,d=.014,c=[Math.cos(a)*r,Math.sin(a)*r,fz(r)],
        sd=[-Math.sin(a),Math.cos(a),0],up=[0,0,1],ring=[];
      for(let j=0;j<14;j++){const q=j/14*TAU,cs=Math.cos(q),sn=Math.sin(q);ring.push(V3.add(c,V3.add(V3.mul(sd,cs*w2),V3.mul(up,sn>0?sn*.0045:sn*d))));}
      rings.push(ring);edge.push(V3.add(c,V3.add(V3.mul(sd,e*w2*.55),[0,0,.0043])));}
    hdPart(spin,mb=>{hdLoft(mb,rings,RIMM,true);hdCap(mb,rings[0],RIMM,true);hdCap(mb,rings[n],RIMM,false);},40);
    /* the machined edge down the spoke's outer side */
    hdPart(spin,mb=>{hdTube(mb,edge.slice(4),.0011,5,CUT,false,true);},40);}
  /* the hub's flat, the cap, the face of the lip (machined) */
  hdPart(spin,mb=>{hdRev(mb,[[r0+.012,fz(r0)+.002],[r0,face+.012],[.05,face+.01],[.042,face+.01]],64,RIMM,0,TAU,true);},40);
  hdPart(spin,mb=>{hdRev(mb,[[.042,face+.01],[.04,face+.024],[.034,face+.03],[0,face+.031]],48,HC.GB,0,TAU,true);},40);
  hdPart(spin,mb=>{hdRev(mb,[[r1-.006,fz(r1)-.004],[r1,fz(r1)+.002],[rimR+.004,zo+.006],[rimR+.012,zo+.004]],128,CUT);},35);
  hdBrake(spin,fixed,w,{ro:.2,ri:.12,zc:-.03,pistons:6});
  return {spin,fixed,tris:(spin.p.length+fixed.p.length)/9};
}

;
/* =====================================================================================
   THE HYPERCAR'S FACE, IN THREE DIMENSIONS (in place of 36_hyper FACES.hyper's decals and 23_parts FRONTS.lip's
   boxes), on the decals' own outlines, in the body-colour nose:
   - The lamps: slim angular slits high on the corners, each a black cavity under one clear lens: the white LED
     light guide along its lower edge in a satin channel, two small projectors in chrome rings above it.
   - The big intakes under them: black pockets set deep into the corners, a fine honeycomb at the back, a gloss
     black blade across each.
   - The slot across the bottom of the nose: a black opening, the same honeycomb in it.
   - The flank intakes behind the doors: deep scoops into the hips, a black pocket with a woven mesh across it and
     two strakes standing in it.
   - The lip (79_parts hdLip, the Coupe's and the EV's), unless the build carries the Track's splitter.
   - The bonnet's vents (hpHoodVents, on the bonnet so they lift with it): each let into the bonnet, a dark
     pocket under black slats.
   (Swept sections are [up, out]: up the face, then out of it.)
   ===================================================================================== */
function hpFace(out,car,opt={}){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,cuts=[car.body,car.hood],X=K.X;
  /* ---------- the lamps ---------- */
  for(const s of [1,-1]){
    const P=[[.47,.49],[.84,.545],[.906,.588],[.914,.6],[.86,.6],[.5,.53]].map(([z,y])=>[s*z,Y(y)]);
    hdLampUnit(out,'F',P,cuts,{deep:.05,k:.86,wall:HC.GB,back:()=>HC.GB,bulge:.0015,cell:.004,lens:()=>HC.LENSH,seal:false,tol:.05,
      inside:o=>{
        /* the light guide along the lower edge, in its satin channel */
        const pts=[[.5,.5045],[.6,.519],[.7,.5335],[.8,.548],[.85,.5595],[.885,.5805]].map(([z,y])=>hdS('F',s*z,Y(y),-.008));
        hdPart(o,mb=>{hdTube(mb,pts,.0032,10,SV([1,1,1],MAT.LED),false,true);},50);
        hdPart(o,mb=>{hdTube(mb,pts.map(p=>V3.add(p,[-.004,-.002,0])),.0055,10,HC.SATIN,false,true);},40);
        /* the two projectors above it: a chrome ring, the lens, the barrel behind it */
        for(const [z,y,r] of [[.64,.5415,.0088],[.74,.5555,.0088]]){const c=hdS('F',s*z,Y(y),-.017);
          hdRevAt(o,'F',c,[[r+.004,-.002],[r+.003,.003],[r+.0005,.004],[r,.002]],MM.CHROME,32);
          hdPart(o,mb=>{ball(mb,V3.add(c,[.001,0,0]),r,16,HC.LAMPH);hdCyl(mb,V3.add(c,[-.004,0,0]),V3.add(c,[-.026,0,0]),r+.002,r,16,HC.SATIN);},50);}}});
    hdTrim(out,'F',hdResample(P,.006),.006,.0025,HC.SEAL,true,50);
  }
  /* ---------- the big intakes ---------- */
  for(const s of [1,-1]){const T=[[.4,.16],[.9,.18],[.9,.44],[.62,.4],[.42,.3]].map(([z,y])=>[s*z,Y(y)]);
    for(const c of cuts)hdCut(c,'F',T);hdRecess(out,'F',T,.13,.9,HC.GB,()=>HC.GB);
    hdHoney(out,'F',hdShrink(T,.86),.05,.013,.0016,.012,HC.HONEY);
    hdTrim(out,'F',hdResample(T,.008),.012,.004,HC.GB,true,50);
    /* the blade across it: a thin gloss black airfoil from the inner edge out to the corner, set a little in */
    hdPart(out,mb=>{const path=[];for(let k=0;k<=10;k++){const z=.46+.42*k/10,y=Y(.255+.12*(k/10)*(k/10)*.6+.03*k/10);path.push(hdS('F',s*z,y,-.03));}
      hdSweep(mb,path,[[-.004,-.006],[.003,-.004],[.004,.03],[-.002,.028]],HC.GB,[1,0,0],true,true);},40);}
  /* ---------- the slot across the bottom ---------- */
  {const S=RR2(-.36,.36,Y(.19),Y(.29),.02);for(const c of cuts)hdCut(c,'F',S);
    hdRecess(out,'F',S,.1,.95,HC.GB,()=>HC.GB);hdHoney(out,'F',hdShrink(S,.94),.04,.013,.0016,.012,HC.HONEY);
    hdTrim(out,'F',hdResample(S,.008),.012,.004,HC.GB,true,50);}
  /* ---------- the flank intakes behind the doors ---------- */
  {const u0=D.G.cB-.05,u1=D.uRa-D.arch.a-.04-(opt.short||0);
    for(const s of [1,-1]){const P=[[u0,Y(.36)],[u1,Y(.34)],[u1+.02,Y(.74)],[u0+.12,Y(.62)]];
      hdCutSide(car.body,s,P,.015);const R=hdResample(P,.006),c=hdCen(R),Bk=R.map(([u,y])=>[c[0]+(u-c[0])*.86,c[1]+(y-c[1])*.9]);
      hdPart(out,mb=>{const F=R.map(([u,y])=>hdSS(s,u,y,-.0005)),B=Bk.map(([u,y])=>hdSS(s,u,y,-.16));hdLoft(mb,[F,B],HC.GB,true);hdCap(mb,B,HC.GB,s<0);},30);
      /* the mesh across it, a little in */
      hdPart(out,mb=>{hpMesh(mb,R.map(([u,y])=>[c[0]+(u-c[0])*.93,c[1]+(y-c[1])*.95]),.016,.0014,HC.HONEY,([u,y],l)=>hdSS(s,u,y,-.05-l));},0);
      /* two strakes standing in it, leaning with its front edge */
      hdPart(out,mb=>{for(const t of [.36,.68]){const a=[u0+(u1-u0)*t+.01,Y(.355)],b=[u0+.12+(u1+.02-u0-.12)*t,Y(.62+.12*t)];const path=[];
          for(let k=0;k<=8;k++){const f=.04+.92*k/8;path.push(hdSS(s,a[0]+(b[0]-a[0])*f,a[1]+(b[1]-a[1])*f,-.004));}
          hdSweep(mb,path,[[-.004,-.05],[.004,-.05],[.003,.0],[-.003,.0]],HC.GB,[0,0,s],true,true);}},40);
      /* its edge rolled in, in paint */
      hdPart(out,mb=>{const E=R.map(([u,y])=>hdSS(s,u,y,-.003));E.push(E[0]);hdTube(mb,E,.0035,6,SV([1,1,1],MAT.PAINT),false,false);},40);}
  }
  if(!opt.track)hdLip(out,car);
}
/* the bonnet's vents, on the decals' own outlines either side of the bonnet's middle */
function hpHoodVents(out,car){
  for(const s of [1,-1])hdVentTop(out,[car.hood],[[.35,s*.18],[.75,s*.3],[.75,s*.5],[.35,s*.4]],{deep:.05,pitch:.026});
}

