/* =====================================================================================
   THE HYPERCAR'S BOLT-ONS AND THE ENGINE COVER, each taken off the game's body and modelled again:
   - The race mirrors (the game's 'race'): 79_parts hdMirrorsRace, the Coupe's and the EV's.
   - The flush door handles: a painted paddle lying flush in the skin, a fine dark gap round it.
   - The engine cover between the hips (36_hyper's mesh panel): the deck opened on the decal's outline, its edge
     turned down into a black lining, black louvres across it every few centimetres, each blade leaning forward so
     the V10 under it (86) shows between them, a spine down the middle holding them.
   ===================================================================================== */
function hpHandles(out,car){
  const K=HDK,D=K.D,G=D.G;
  for(const u of D.B.handles||[G.pillars[0][0]-.2]){const y=D.belt(u)-.09;
    hdDrop(car.body,(c,m)=>{const uu=D.uC-c[0];return Math.abs(uu-(u-.015))<.1&&Math.abs(c[1]-y)<.03&&(m===MAT.COL||m===MAT.CHROME||m===MAT.SHUT)&&hdOff(c)>.002;});
    for(const s of [1,-1])hdFlush(out,car,s,RR2(u-.09,u+.06,y-.014,y+.014,.012),.008);}
}
/* the cover's outline (u, z), the decal's own */
function hpCoverP(){const D=HDK.D,G=D.G;return RR2(G.be+.12,D.L-.35,-.42,.42,.04);}
function hpCover(out,car){
  const K=HDK,D=K.D,P=hpCoverP(),R=hdResample(P,.008);
  hdCutTop(car.body,P,.03);
  /* the edge turned down into a black lining, and a fine black trim round the top of it */
  hdPart(out,mb=>{const F=R.map(([u,z])=>hdTS(u,z,.0006)),B=R.map(([u,z])=>hdTS(u,z,-.035));hdLoft(mb,[F,B],HC.GB,true);},30);
  hdPart(out,mb=>{const E=R.map(([u,z])=>hdTS(u,z,-.001));E.push(E[0]);hdTube(mb,E,.004,6,HC.GB,false,false);},40);
  /* the louvres across it */
  let u0=1e9,u1=-1e9;for(const [u] of P){u0=Math.min(u0,u);u1=Math.max(u1,u);}
  const span=u=>{const T=hpClip(P,[u,0],[0,1]);return T||[0,0];};
  hdPart(out,mb=>{for(let u=u0+.026;u<u1-.016;u+=.032){const [a,b]=span(u);if(b-a<.05)continue;const path=[];for(let z=a+.006;z<=b-.006+1e-6;z+=.04)path.push(hdTS(u,z,-.007));path.push(hdTS(u,b-.006,-.007));
    hdSweep(mb,path,[[-.0022,-.024],[.0022,-.024],[.003,0],[-.0012,0]],HC.GB,[.6,1,0],true,true);}},35);
  /* the spine down the middle and two rails along the sides under the blades */
  hdPart(out,mb=>{for(const z of [0,-.3,.3]){const path=[];for(let u=u0+.02;u<=u1-.02+1e-6;u+=.04)path.push(hdTS(u,z,z?-.03:-.012));
    hdSweep(mb,path,[[-.008,-.03],[.008,-.03],[.008,0],[-.008,0]],HC.GB,[0,1,0],true,true);}},35);
}

;
/* =====================================================================================
   THE HYPERCAR'S CABIN (79_cabin hdCabinGen, the SUV Studio's way, with its screens and controls added here): a
   modern two-seat cockpit in black with the build's accent colour. A low, bare dash; a slim display standing on
   the column in place of dials and a landscape screen on the middle of the dash; a three-spoke wheel with a
   coloured mark at the top and two shift paddles behind it; no lever (the seven-speed is picked by buttons on the
   console's bridge, beside a starter under a flip cover); two deep carbon-backed buckets with a coloured stripe;
   behind them the bulkhead, trimmed to the sill, and the glass over it that shows the engine (86).
   (The seats sit as low as the floor allows, well forward under the canopy's crown, so the headrests clear the
   glass: the backrest's top stands about 0.8 m above its pivot.)
   ===================================================================================== */
function hpCabin(out,car){
  const D=HDK.D,G=D.G,X=HDK.X,uEnd=2.86,ACC=car.b.cal||'#e8b21b',
    o={floorY:.175+D.dy,uEnd,headEnd:G.rr-.04,doors:2,armY:.24,dashDepth:.42,
    dashTop:D.belt(G.cowl+.42)-.03,hoodH:.025,dials:[],clusterW:.17,vents:[-.62,-.12,.12,.62],stackW:.12,
    wheelU:.1,wheelDrop:.09,wheelR:.17,rimT:.02,spokes:[0,PI,-PI/2],spokeT:.014,spokeM:SMC('#1c1c1e',SM.SATIN),hub:[.065,.065,.03],
    shifter:'none',console:'small',consoleBack:-.1,seatF:2.3,seatY:.08,seatZ:.38,seatW:.5,bolster:2,seatStripe:1,rear:'none',back:'cab',
    tunnel:.13,toe:.16,tunnelEnd:uEnd,
    col:{dash:'#18181a',dashTop:'#121213',vinyl:'#1f1f21',insert:'#2a2a2d',head:'#222224',carpet:'#19191a',seat:'#202022',seatSide:'#18181a',accent:ACC}};
  hdCabinGen(out,car,o);
  /* (the door panels' top roll, made for an upright side, stands a few millimetres out through the skin under this
     canopy's tumblehome: every point of the cabin along the sill is tucked back inside the skin) */
  {const p=out.p,K=HDK;for(let i=0;i<p.length;i+=3){const u=D.uC-p[i],y=p[i+1];if(u<G.cowl||u>uEnd+.05)continue;const b=D.belt(u);if(y<b-.05||y>b+.03)continue;
    const zs=K.sideZ(u,y)-.006;if(Math.abs(p[i+2])>zs)p[i+2]=Math.sign(p[i+2])*zs;}}
  /* (the game's black trim along the side glass's foot, which the cabin's cut leaves in a sawtooth where the
     window's outline crosses it, off; a clean rubber seal along the foot of the glass in its place) */
  {const K=HDK,uA=G.cowl+.02,uZ=G.cB+.08;
    hdDrop(car.body,(c,m,cl)=>{if(m!==MAT.COL||Math.abs(cl-.010)>1e-4)return false;const u=D.uC-c[0];if(u<uA||u>uZ)return false;const b=D.belt(u);
      return c[1]>b+.004&&c[1]<b+.04&&Math.abs(Math.abs(c[2])-K.sideZ(u,c[1]))<.03;});
    for(const s of [1,-1])hdPart(out,mb=>{const path=[];for(let u=G.cowl+.06;u<=G.cB-.025+1e-6;u+=.02){const y=D.belt(u)+.0195;path.push([X(u),y,s*(K.sideZ(u,y)-.004)]);}
      hdTube(mb,path,.0095,8,HC.SEAL,false,true);},40);}
  const uE=G.cowl+o.dashDepth,yt=o.dashTop,dz=-.38,SCR=SV(lin('#0b1620'),SM.GLOSSBLK),UI=SV(lin('#dfe8f0'),MAT.COL,.8),BEZ=HC.GB,AC=SMC(ACC,SM.VINYL),
    CARB=SV([1,1,1],MAT.CARBON);
  /* the driver's display, standing on the column above the wheel's hub: a dark glass in a thin bezel, leaning back */
  {const c=[X(uE-.02),yt+.035,dz],n=V3.norm([-1,.35,0]),up=V3.norm([.35,1,0]),M=M4.basis(c,V3.mul(n,-1),up,[0,0,1]);
    hdPart(out,mb=>{hdRBox(mb,[0,0,0],[.008,.042,.12],.01,BEZ,3);},30,null,M);
    hdPart(out,mb=>{hdRBox(mb,[-.0085,0,0],[.0015,.035,.112],.006,SCR,1);},20,null,M);
    hdPart(out,mb=>{for(const [y2,z2,h,w] of [[.006,0,.012,.028],[-.02,0,.003,.09],[.018,.08,.004,.02],[.018,-.08,.004,.02],[-.004,-.07,.012,.003],[-.004,.07,.012,.003]])hdRBox(mb,[-.0102,y2,z2],[.0005,h,w],.0005,UI,1);},20,null,M);
    hdPart(out,mb=>{hdRBox(mb,[.03,-.04,0],[.03,.012,.05],.008,BEZ,2);},30,null,M);}
  /* the screen on the middle of the dash: a landscape glass in a black bezel, leaning back */
  {const c=[X(uE-.06),yt-.075,0],n=V3.norm([-1,.3,0]),up=V3.norm([.3,1,0]),M=M4.basis(c,V3.mul(n,-1),up,[0,0,1]);
    hdPart(out,mb=>{hdRBox(mb,[0,0,0],[.008,.07,.11],.01,BEZ,3);},30,null,M);
    hdPart(out,mb=>{hdRBox(mb,[-.0085,0,0],[.0015,.063,.102],.006,SCR,1);},20,null,M);
    hdPart(out,mb=>{hdRBox(mb,[-.0102,.05,0],[.0005,.0015,.09],.0005,UI,1);for(let k=0;k<3;k++)hdRBox(mb,[-.0102,.02-k*.025,-.05],[.0005,.006,.04],.0005,SV(lin('#4d5660'),SM.GLOSSBLK),1);
      hdRBox(mb,[-.0102,-.01,.05],[.0005,.045,.045],.0005,SV(lin('#1d3a52'),SM.GLOSSBLK),1);},20,null,M);}
  /* the console's bridge: a carbon plate over the front of the console, the gear buttons in a row, the starter
     under a flip cover in the accent colour */
  {const u=uE+.16,y=o.floorY+.235,ax=V3.norm([1,-.35,0]),ay=V3.norm([.35,1,0]),M=M4.basis([X(u),y,0],ax,ay,[0,0,1]);
    hdPart(out,mb=>{hdRBox(mb,[0,0,0],[.12,.008,.085],.012,CARB,3);},30,null,M);
    hdPart(out,mb=>{for(const z of [-.05,-.017,.017])hdRBox(mb,[-.03,.01,z],[.018,.004,.013],.004,BEZ,2);for(const z of [-.05,-.017,.017])hdRBox(mb,[-.03,.0145,z],[.008,.0005,.004],.0004,UI,1);},30,null,M);
    hdPart(out,mb=>{hdCyl(mb,[-.03,.008,.055],[-.03,.016,.055],.014,.014,20,SMC('#b51d18',SM.VINYL));hdRBox(mb,[-.045,.028,.055],[.002,.018,.018],.003,AC,2);},30,null,M);
    /* the rotary drive-mode knob behind them */
    hdPart(out,mb=>{hdCyl(mb,[.06,.008,0],[.06,.03,0],.022,.02,24,HC.SATIN);hdCyl(mb,[.06,.03,0],[.06,.032,0],.018,.018,24,BEZ);},30,null,M);}
  /* the wheel's mark at the top, and the paddles behind it */
  {const c=[X(uE+o.wheelU),yt-o.wheelDrop,dz],n=V3.norm([-.9,.44,0]),f=V3.norm([.44,.9,0]),M=M4.basis(c,f,[0,0,-1],n);
    hdPart(out,mb=>{const path=[];for(let k=-3;k<=3;k++){const a=k/72*TAU;path.push([Math.cos(a)*o.wheelR,Math.sin(a)*o.wheelR,0]);}hdTube(mb,path,o.rimT+.0008,14,AC,false,false);},45,null,M);
    hdPart(out,mb=>{for(const e of [1,-1]){const p=[[.02,e*.06,-.04],[.04,e*.12,-.045],[.1,e*.17,-.05],[.12,e*.19,-.05]];hdSweep(mb,p,[[-.012,-.003],[.012,-.003],[.012,.003],[-.012,.003]],CARB,[0,0,1],true,true);}},40,null,M);}
  /* the glass over the bulkhead, from its trimmed wall up to the canopy, and the wall's back (86 builds the bay) */
  {const u=uEnd+.015,x=X(u),yb=D.belt(u)-.01,rows=[];
    for(let k=0;k<=24;k++){const z=-1+2*k/24,row=[];for(let j=0;j<=6;j++){const y=yb+(HDK.topY(u,Math.min(.95,Math.abs(z)))-.012-yb)*j/6,zz=Math.min(Math.abs(z),HDK.sideZ(u,y)-.04)*Math.sign(z);row.push([x,y,zz]);}rows.push(row);}
    hdPart(out,mb=>{hdLoft(mb,rows,SV([1,1,1],MAT.GLASS),false);},30);
    hdPart(out,mb=>{const r=rows.map(rw=>rw[0]);hdTube(mb,r,.008,6,HC.SEAL,false,false);},30);}
}

;
/* =====================================================================================
   THE HYPERCAR'S V10 AND THE BAY ROUND IT, behind the cabin, seen through the canopy's long rear glass and between
   the engine cover's louvres (84). Built here, as the game draws no engine there (31_engine_bay draws a front bay,
   which 87 keeps as a front trunk).
   - The bay: a floor, the side walls with a ledge out to the skin, the rear wall behind the silencer, all in dark grey
     liner; the bulkhead behind the cabin faced in gold heat foil; a carbon strut brace across between the towers.
   - The V10, lengthwise ahead of the rear axle, its crank low: the block and its sump in cast grey, two cylinder
     heads at ninety degrees, cam covers in red crinkle with fins along them and five coils down each in the
     build's accent colour; between the banks a carbon plenum with ten short runners into the heads, two throttle
     bodies at its front fed by ducts from the carbon air boxes either side (the flank intakes' air).
   - The exhaust: five primaries a bank curling out and down from the heads into a collector, a pipe from each
     back over the drive shafts to the silencer across the tail, two pipes out of its back to the tips (83).
   - The transaxle behind the engine: the bell housing, the differential across the axle line, the gearbox case
     behind it; the drive shafts out to the wheels with their joints' boots.
   - The dry-sump oil tank and the coolant header tank either side, ahead of the rear wheels.
   ===================================================================================== */
function hpEngine(out,car){
  const K=HDK,D=K.D,X=K.X,lk=D.look,ACC=car.b.cal||'#e8b21b',
    LIN=SMC('#2b2c2f',SM.LINER),FOIL=SMC('#b89238',SM.BRUSH),CASTG=SMC('#3b3c3f',SM.ENGINE),ALU=SMC('#8a8d92',SM.ENGINE),COVER=SMC('#8c1a12',SM.ENGINE),DARKE=SMC('#151517',SM.ENGINE),FIN=SMC('#9a9da2',SM.BRUSH),
    CARB=SV([1,1,1],MAT.CARBON),COIL=SMC('#121213',SM.PLASTIC),CAP=SMC(ACC,SM.PLASTIC),HDR=SMC('#7a6a5a',SM.BRUSH),STEEL=SMC('#b6b9bd',SM.BRUSH),
    HOSE=SMC('#141414',SM.HOSE),BOOT=SV([.02,.02,.02],MAT.RUBBER),TANK=SMC('#d8d4c8',SM.PLASTIC);
  const uB=2.885,uW=4.46,yFl=.16,zW=.66,yc=.31,ue0=2.98,ue1=3.6,um=(ue0+ue1)/2,tip=hpTipAt();
  /* ---------- the bay ---------- */
  const yTop=u=>Math.min(K.topY(u,zW+.02)-.022,D.belt(u)+.3);
  hdPart(out,mb=>{const n=40;for(let k=0;k<n;k++){const a=uB+(uW-uB)*k/n,b=uB+(uW-uB)*(k+1)/n;
    mb.quad([X(a),yFl,-zW],[X(b),yFl,-zW],[X(b),yFl,zW],[X(a),yFl,zW],LIN[0],0,LIN[2]);
    for(const s of [1,-1]){const q=s<0?(p,q2,r,t)=>mb.quad(p,q2,r,t,LIN[0],0,LIN[2]):(p,q2,r,t)=>mb.quad(t,r,q2,p,LIN[0],0,LIN[2]);
      q([X(a),yTop(a),s*zW],[X(b),yTop(b),s*zW],[X(b),yFl,s*zW],[X(a),yFl,s*zW]);
      const za=K.sideZ(a,yTop(a))-.012,zb=K.sideZ(b,yTop(b))-.012;
      q([X(a),yTop(a),s*za],[X(b),yTop(b),s*zb],[X(b),yTop(b),s*zW],[X(a),yTop(a),s*zW]);}}},30);
  /* the rear wall, and the bulkhead's back in its foil (quilted in squares) */
  hdPart(out,mb=>{const x=X(uW),n=16;for(let k=0;k<n;k++){const za=-zW+2*zW*k/n,zb=-zW+2*zW*(k+1)/n,ya=K.topY(uW,Math.abs(za))-.02,yb=K.topY(uW,Math.abs(zb))-.02;
    mb.quad([x,ya,za],[x,yb,zb],[x,yFl,zb],[x,yFl,za],LIN[0],0,LIN[2]);}},30);
  hdPart(out,mb=>{const x=X(uB),yT=D.belt(uB)-.01,nz=12,ny=6;for(let i=0;i<nz;i++)for(let j=0;j<ny;j++){const za=-zW+2*zW*i/nz,zb=-zW+2*zW*(i+1)/nz,ya=yFl+(yT-yFl)*j/ny,yb=yFl+(yT-yFl)*(j+1)/ny,
    zm=(za+zb)/2,ym=(ya+yb)/2,c=[x-.006,ym,zm];
    for(const [p,q] of [[[x,ya,za],[x,ya,zb]],[[x,ya,zb],[x,yb,zb]],[[x,yb,zb],[x,yb,za]],[[x,yb,za],[x,ya,za]]])mb.tri(p,q,c,FOIL[0],0,FOIL[2]);}},25);
  /* the strut brace across between the towers, under the rear glass */
  {const u=3.45,y=Math.min(K.topY(u,.6)-.07,.86);
    hdPart(out,mb=>{hdCyl(mb,[X(u),y,-zW+.02],[X(u),y,zW-.02],.022,.022,20,CARB,true);
      for(const s of [1,-1]){hdRBox(mb,[X(u),y,s*(zW-.03)],[.05,.035,.012],.008,ALU,2);for(const du of [-.03,.03])hdCyl(mb,[X(u+du),y+.02,s*(zW-.045)],[X(u+du),y+.02,s*(zW-.02)],.006,.006,8,HC.BOLT);}},35);}
  /* ---------- the V10 ---------- */
  const EM=M4.basis([X(ue0),0,0],[0,0,1],[0,1,0],[-1,0,0]);
  /* the block and its sump: one section along the crank, the vee between the banks */
  hdPart(out,mb=>{hdExtrude(mb,[[-.13,yc-.14],[.13,yc-.14],[.17,yc-.07],[.2,yc-.01],[.212,yc+.072],[.083,yc+.2],[0,yc+.12],[-.083,yc+.2],[-.212,yc+.072],[-.2,yc-.01],[-.17,yc-.07]],0,ue1-ue0,CASTG,.006,2);},30,null,EM);
  /* the front of the engine: the timing cover, the crank's damper */
  hdPart(out,mb=>{hdRBox(mb,[X(ue0)+.012,yc+.08,0],[.012,.17,.2],.04,CASTG,3);hdCyl(mb,[X(ue0)+.024,yc,0],[X(ue0)+.05,yc,0],.075,.075,32,DARKE,true);},30);
  for(const s of [1,-1]){const c45=Math.SQRT1_2,ay=[0,c45,s*c45],ax=[-1,0,0],az=[0,s*c45,-c45],
      BM=M4.basis([X(um),yc,0],ax,ay,az),bank=s>0?.04:-.04,L2=(ue1-ue0)/2;
    /* the head, the cam cover and its fins, the five coils */
    hdPart(out,mb=>{hdRBox(mb,[0,.265,0],[L2-.005,.06,.098],.02,ALU,3);},30,null,BM);
    hdPart(out,mb=>{hdRBox(mb,[0,.355,0],[L2-.02,.032,.088],.028,COVER,4);},35,null,BM);
    hdPart(out,mb=>{for(const zz of [-.06,-.03,.03,.06])hdRBox(mb,[0,.389,s*zz],[L2-.06,.004,.0035],.002,FIN,1);},30,null,BM);
    hdPart(out,mb=>{for(let i=0;i<5;i++){const x=-L2+.07+i*(ue1-ue0-.14)/4+bank*.5;
        hdCyl(mb,[x,.38,0],[x,.418,0],.017,.017,16,COIL,true);hdCyl(mb,[x,.418,0],[x,.426,0],.019,.015,16,CAP,true);hdRBox(mb,[x,.408,-s*.024],[.01,.008,.008],.003,COIL,2);}},35,null,BM);
    /* the exhaust: five primaries curling out and down from the head into a collector behind it */
    const port=(i,d)=>{const x=-L2+.07+i*(ue1-ue0-.14)/4+bank*.5;return M4.xform(BM,[x,.27,s>0?-.108-d:.108+d]);};
    hdPart(out,mb=>{const col=[X(ue1+.02),yc-.01,s*.36];for(let i=0;i<5;i++){const p0=port(i,0),p1=port(i,.04),p2=[p1[0],p1[1]-.08,s*(Math.abs(p1[2])+.06)],
        p3=[X(ue1-.08+i*.02),yc-.02,s*.4];hdTube(mb,[p0,p1,p2,p3,col].map((p,k)=>k===4?V3.add(p,[0,0,s*(i-2)*.008]):p),.017,10,HDR,false,true);}
      hdCyl(mb,[X(ue1-.04),yc-.01,s*.37],[X(ue1+.06),yc-.01,s*.37],.04,.035,16,HDR,true);},30);
    /* the pipe back over the drive shaft to the silencer */
    hdPart(out,mb=>{hdTube(mb,[[X(ue1+.05),yc-.01,s*.37],[X(3.72),.46,s*.42],[X(3.9),.47,s*.42],[X(4.14),.45,s*.42]],.034,14,STEEL,false,true);},35);
    /* the runners from the plenum into the head's inner side */
    hdPart(out,mb=>{for(let i=0;i<5;i++){const p0=port(i,0).slice(),pin=M4.xform(BM,[-L2+.07+i*(ue1-ue0-.14)/4+bank*.5,.27,s>0?.11:-.11]);
        const m1=[pin[0],pin[1]+.05,pin[2]+s*.04],a=[pin[0],yc+.345,s*.098];hdTube(mb,[pin,m1,a],.021,12,CARB,false,true);}},35);
    /* the air box beside the engine and its duct to the throttle body */
    hdPart(out,mb=>{hdRBox(mb,[X(3.13),.66,s*.5],[.14,.065,.1],.04,CARB,4);hdTube(mb,[[X(3.02),.66,s*.4],[X(2.98),.665,s*.25],[X(3.0),.66,s*.13]],.042,16,ALU,false,true);},35);
    hdPart(out,mb=>{hdCyl(mb,[X(3.0),.66,s*.13],[X(3.06),.655,s*.07],.04,.04,20,ALU,true);},35);}
  /* the plenum between the banks */
  hdPart(out,mb=>{hdRBox(mb,[X(um+.02),yc+.34,0],[.27,.042,.1],.038,CARB,5);hdRBox(mb,[X(um+.02),yc+.383,0],[.22,.005,.07],.005,FIN,2);},35);
  /* the oil tank and the coolant header tank */
  hdPart(out,mb=>{hdCyl(mb,[X(3.42),yFl+.02,.55],[X(3.42),.58,.55],.065,.065,28,ALU,true);hdCyl(mb,[X(3.42),.58,.55],[X(3.42),.605,.55],.033,.033,20,DARKE,true);
    hdRBox(mb,[X(3.42),.6,-.55],[.07,.06,.07],.02,TANK,3);hdCyl(mb,[X(3.42),.66,-.55],[X(3.42),.685,-.55],.028,.028,20,CAP,true);
    hdTube(mb,[[X(3.36),.24,.5],[X(3.2),.2,.3],[X(3.1),.19,.12]],.014,10,HOSE,false,true);hdTube(mb,[[X(3.36),.58,-.5],[X(3.2),.52,-.3],[X(3.04),.46,-.15]],.012,10,HOSE,false,true);},35);
  /* ---------- the transaxle and the drive shafts ---------- */
  hdPart(out,mb=>{hdCyl(mb,[X(ue1-.01),yc,0],[X(ue1+.12),yc+.01,0],.17,.14,36,ALU,true);
    hdCyl(mb,[X(D.uRa+.02),.33,-.2],[X(D.uRa+.02),.33,.2],.11,.11,32,ALU,true);
    hdRBox(mb,[X(3.95),.3,0],[.19,.12,.14],.05,ALU,4);
    for(const du of [-.12,0,.12])hdRBox(mb,[X(3.95+du),.42,0],[.008,.006,.1],.004,ALU,1);},30);
  for(const s of [1,-1])hdPart(out,mb=>{const y=D.arch.cy,z0=.2,z1=lk.track/2-lk.tyre.W/2-.02;
    hdCyl(mb,[X(D.uRa),y,s*z0],[X(D.uRa),y,s*z1],.022,.022,14,STEEL,false);},30);
  for(const s of [1,-1])for(const zb of [.2,lk.track/2-lk.tyre.W/2-.12])hdPart(out,mb=>{hdRev(mb,[[.028,0],[.05,.02],[.042,.04],[.05,.06],[.035,.08],[.028,.1]],20,BOOT);},30,null,M4.basis([X(D.uRa),D.arch.cy,s*zb],[1,0,0],[0,s,0],[0,0,s]));
  /* ---------- the silencer across the tail and the two pipes to the tips ---------- */
  hdPart(out,mb=>{hdRBox(mb,[X(4.28),.45,0],[.13,.1,.5],.06,STEEL,5);for(const du of [-.08,-.03,.03,.08])hdRBox(mb,[X(4.28+du),.553,0],[.006,.004,.46],.003,STEEL,1);},35);
  hdPart(out,mb=>{for(const s of [1,-1])hdTube(mb,[[X(4.36),tip.y,s*tip.z],[X(4.43),tip.y,s*tip.z]],.058,24,STEEL,false,false);},35);
}

;
/* =====================================================================================
   THE HYPERCAR'S FRONT TRUNK (79_bay hdBayGen, its mid-engine layout): no engine under the bonnet, so a small
   front trunk in its place, moulded in black, with what a mid-engined car keeps in its nose round it: the
   radiators and their two electric fans, the 12-volt battery, the brake booster, the fuse box, the washer bottle.
   (The game draws an engine for this bay from its spec; the Studio shows what a mid-engined car has there: its
   V10 is behind the cabin, 86.)
   ===================================================================================== */
function hpBay(car){return hdBayGen(car,{engine:{layout:'MID',efans:1},tubeR:.04});}

;
/* =====================================================================================
   THE HYPERCAR TRACK IN THE STUDIO: the game's track edition of the Hypercar (37_newbuilds hyperTrack: "Downforce
   you can feel at walking pace"), built on the Stock's Studio parts (../hyper, hpBuild: the face, tail, tips,
   cabin, engine cover, the V10 and the front trunk), with the Track's own built again in this folder: 81 the
   slick on its centre-lock wheel, 82 the aero (the splitter and its canards, the tow strap, the side skirts, the
   roof scoop, the shark fin and the swan-neck wing). The widebody's flares are the SUV Studio's (73_arch
   hdFlares), in the paint; the flank intakes are cut a little shorter, clear of them. The stripes are the game's.
   ===================================================================================== */
HD_CARS.hyperTrack={
  skip:{FACES:['hyper'],TAILS:['hyper'],FRONTS:['race'],REARS:['coupeDiff'],EXTRAS:['skirts','fin','roofScoop']},
  build(out){hpBuild(out,{wheel:hkWheel,track:hkKit,short:.1});},
  views:{cabin:D=>{const G=D.G,u=G.rr-.05;return {p:[D.X(u),D.belt(u)+.36,1.75],t:[D.X(G.cowl+.5),D.belt(u)-.25,-.25]};}}
};

;
/* =====================================================================================
   THE HYPERCAR TRACK'S WHEEL: a 330/680R20 slick on the 20-inch centre-lock race wheel the game gives it
   (30_wheels 'race'), modelled for a close look. Same axes and size as the game's wheel.
   - The slick (hkSlick): the carcass turned as the road tyres' is (78_run's profile), then no tread at all: a smooth,
     gently crowned crown rounding over broad shoulders onto the sidewall, three small wear-gauge holes across it
     at four places round it, a thin band in the build's second colour on the sidewall.
   - The wheel, in the build's dark grey: six spokes from a deep centre, each splitting into two slim spokes out to
     the lip, rounded across, falling concave to the hub; the machined lip.
   - The centre lock: the big hexagon nut in the build's orange over the drive pegs, the safety pin through it.
   - The brake (78_run hdBrake): the big ventilated rotor and a six-piston caliper in the build's orange.
   ===================================================================================== */
function hkSlick(out,w){
  const R=w.R,W=w.W,hw=W/2,rimR=w.rim*.0254/2,sh=R-rimR,steps=Math.round(192*Math.max(1,R/.378)),base=R-.012,fb=(base-rimR)/sh;
  /* the carcass, bead to shoulder (78_run hdTyre's profile, without its fine rings) */
  const P=[[.02,.765],[.08,.805],[.15,.865],[.22,.925],[.262,.968],[.29,.99],[.318,.986],[.345,.966],[.42,.976],[.5,1.0],[.58,1.0],[.66,.996],[.74,.986],[.8,.968],[.86,.94],[.92,.9],[fb,.87]];
  const half=P.map(([f,g])=>[rimR+f*sh,g*hw]),tz=P[P.length-1][1]*hw;
  hdPart(out,mb=>{hdRev(mb,half,steps,HC.WALL,0,TAU,true);hdRev(mb,half.map(([r,z])=>[r,-z]),steps,HC.WALL);},28);
  /* the crown: smooth, crowned a few millimetres, its shoulders rounded */
  const crown=[];for(let i=0;i<=24;i++){const t=-1+2*i/24,a=Math.abs(t),sh2=a>.86?Math.sqrt(Math.max(0,1-Math.pow((a-.86)/.14,2))):1;
    crown.push([base+(R-.003*t*t-base)*sh2,t*tz]);}
  hdPart(out,mb=>{hdRev(mb,crown,steps,HC.TREAD);},40);
  /* the wear gauges: three small holes across the crown at four places round it */
  hdPart(out,mb=>{for(let q=0;q<4;q++){const a0=q/4*TAU+.3;for(const zf of [-.45,0,.45]){const z=zf*tz,r=R-.003*zf*zf-.0002,n=8,ring=[],ringB=[];
      for(let k=0;k<n;k++){const t=k/n*TAU,da=Math.cos(t)*.003/r,dz=Math.sin(t)*.003;ring.push([Math.cos(a0+da)*r,Math.sin(a0+da)*r,z+dz]);ringB.push([Math.cos(a0+da)*(r-.003),Math.sin(a0+da)*(r-.003),z+dz*.8]);}
      hdLoft(mb,[ring,ringB],SV([.012,.012,.013],SM.TREAD),true,true);hdCap(mb,ringB,SV([.012,.012,.013],SM.TREAD),false);}}},0);
  /* the coloured band on the outer sidewall */
  hdPart(out,mb=>{const f0=.5,f1=.56,r0=rimR+f0*sh,r1=rimR+f1*sh;hdRev(mb,[[r1,hw*1.003],[r0,hw*1.003]],steps,SV([1,1,1],MAT.ACCENT));},30);
  return {R,W,hw,rimR,sh};
}
function hkWheel(w){
  const spin=new MB(),fixed=new MB();hkSlick(spin,w);
  const rimR=w.rim*.0254/2,hw=w.W/2,zo=hw*.77,RIMM=SV([1,1,1],MAT.RIM),CUT=SMC('#6d7076',SM.BRUSH),CAL=SV([1,1,1],MAT.CALIPER),face=zo-.07,r0=.085,r1=rimR-.008;
  const fz=r=>face+.014+(zo-.002-face-.014)*Math.pow(clamp((r-r0)/(r1-r0),0,1),.7);
  hdRimParts(spin,w,{lugs:0,face:face+.01,lip:RIMM,barrel:HC.CAST,valveA:PI/6});
  /* the spokes: six, each splitting into two slim ones halfway out */
  for(let k=0;k<6;k++)for(const e of [-1,1]){const am=k/6*TAU,n=16,rings=[];
    for(let i=0;i<=n;i++){const t=i/n,r=r0+(r1-r0)*t,sp=Math.max(0,t-.38)/.62,a=am+e*(.012+.1*Math.pow(sp,1.1)),w2=(t<.38?.0145:.0145-.007*sp)-.001*t,d=.016,c=[Math.cos(a)*r,Math.sin(a)*r,fz(r)],
        sd=[-Math.sin(a),Math.cos(a),0],up=[0,0,1],ring=[];
      for(let j=0;j<14;j++){const q=j/14*TAU,cs=Math.cos(q),sn=Math.sin(q);ring.push(V3.add(c,V3.add(V3.mul(sd,cs*w2),V3.mul(up,sn>0?sn*.0045:sn*d))));}
      rings.push(ring);}
    hdPart(spin,mb=>{hdLoft(mb,rings,RIMM,true);hdCap(mb,rings[0],RIMM,true);hdCap(mb,rings[n],RIMM,false);},40);}
  /* the deep centre, its drive pegs, the hexagon nut and the safety pin */
  hdPart(spin,mb=>{hdRev(mb,[[r0+.012,fz(r0)+.002],[r0,face+.014],[.062,face+.012],[.056,face+.006]],72,RIMM,0,TAU,true);},40);
  hdPart(spin,mb=>{for(let k=0;k<6;k++){const a=k/6*TAU+PI/6;hdCyl(mb,[Math.cos(a)*.066,Math.sin(a)*.066,face+.004],[Math.cos(a)*.066,Math.sin(a)*.066,face+.016],.006,.006,10,HC.BOLT);}},30);
  hdPart(spin,mb=>{const hx=(r,z)=>{const o=[];for(let i=0;i<6;i++){const t=i/6*TAU;o.push([Math.cos(t)*r,Math.sin(t)*r,z]);}return o;};
    const rings=[hx(.052,face+.006),hx(.056,face+.012),hx(.056,face+.038),hx(.05,face+.046)];hdLoft(mb,rings,CAL,true);hdCap(mb,rings[3],CAL,true);},20);
  hdPart(spin,mb=>{hdRev(mb,[[.034,face+.046],[.03,face+.054],[.018,face+.058],[0,face+.058]],32,CAL,0,TAU,true);},35);
  hdPart(spin,mb=>{hdCyl(mb,[-.05,0,face+.05],[.05,0,face+.05],.0035,.0035,10,MM.CHROME);ball(mb,[.052,0,face+.05],.008,12,MM.CHROME);},35);
  hdPart(spin,mb=>{hdRev(mb,[[r1-.006,fz(r1)-.004],[r1,fz(r1)+.002],[rimR+.004,zo+.006],[rimR+.012,zo+.004]],128,CUT);},35);
  hdBrake(spin,fixed,w,{ro:.2,ri:.12,zc:-.03,pistons:6});
  return {spin,fixed,tris:(spin.p.length+fixed.p.length)/9};
}

;
/* =====================================================================================
   THE HYPERCAR TRACK'S AERO, IN THREE DIMENSIONS (in place of 23_parts FRONTS.race's and EXTRAS.skirts' boxes,
   36_hyper EXTRAS.fin's plate, 29_hatch EXTRAS.roofScoop's box and 23_parts deckWing's, which nothing skips and
   is taken off the game's body here), all in carbon unless said:
   - The splitter: a plate following the nose well ahead of it, its front edge rolled up into a lip, three strakes a
     side under it, two stays up to the nose, a fence at each end; two canards a side on the nose's corners; a red
     tow strap looped under the slot.
   - The side skirts: a blade along each sill between the arches, standing out and turned down at its edge.
   - The roof scoop on the canopy, in the paint: a rounded hood rising from the glass to its mouth, the mouth black
     inside with a mesh across it.
   - The shark fin down the spine from the roof to the wing, thin, its top edge rounded.
   - The swan-neck wing: a cambered main plane right across the tail on the game's span and chord, a Gurney strip
     along its trailing edge; the endplates; two swan necks rising from the deck behind it, over its top and down
     onto it, on feet bolted to the deck.
   ===================================================================================== */
function hkKit(out){
  const a=new MB();hkSplitter(a,out);hkSkirts(a,out);hkScoop(a,out);hkFin(a,out);hkWing(a,out);out.hd.aero=a;
}
const hkCARB=()=>SV([1,1,1],MAT.CARBON);
function hkSplitter(out,car){
  const K=HDK,D=K.D,X=K.X,F=D.B.fit,y=K.dy+F.fdy+.4,C=hkCARB(),n=36,zw=.9;
  /* the plate: the game's outline, the front edge rolled up */
  const fr=z=>K.uFront(Math.abs(z)*.95,y+.05)-.14,uB=.35;
  const sec=(z)=>{const u0=fr(z),u1=Math.max(u0+.12,uB);return [[u0+.012,0],[u0+.002,.004],[u0,.012],[u0+.004,.019],[u0+.014,.021],[u0+.03,.012],[u1,.012],[u1,0]].map(([u,h])=>[X(u),y+h,z]);};
  const rows=[];for(let k=0;k<=n;k++){const t=k/n,z=-zw+2*zw*(.5-.5*Math.cos(t*PI));rows.push(sec(z));}
  hdPart(out,mb=>{hdLoft(mb,rows,C,true);hdCap(mb,rows[0],C,true);hdCap(mb,rows[n],C,false);},40);
  /* the strakes under it, the stays up to the nose, the fences at its ends */
  for(const s of [1,-1]){
    for(const z of [.28,.5,.7])hdPart(out,mb=>{const u0=fr(s*z)+.05;hdExtrude(mb,[[X(u0),y],[X(u0+.02),y-.03],[X(uB-.02),y-.03],[X(uB),y]],s*z-.003,s*z+.003,C,.001,1,true);},30);
    hdPart(out,mb=>{const z=s*.35,u=fr(z)+.1;hdCyl(mb,[X(u),y+.012,z],[X(u+.08),y+.14,z],.006,.006,10,HC.BOLT);ball(mb,[X(u+.08),y+.14,z],.009,10,HC.GB);},35);
    {const u0=fr(s*zw),ep=u0+(F.epU==null?.08:F.epU);
      hdPart(out,mb=>{hdExtrude(mb,[[X(u0),y],[X(ep),y],[X(ep+.02),y+.13],[X(u0)-.02,y+.06]],s*zw-.004,s*zw+.004,C,.0015,2,true);},35);}
    /* the canards */
    for(const [yy,du] of [[.62,.05],[.53,.03]]){const Y=yy+K.dy+F.fdy,u0=K.uFront(.8,Y)+du,ax=[1,0,0],ay=[0,0,s],az=[0,-s,0];
      hdPart(out,mb=>{hdExtrude(mb,[[0,.78],[-.24,.94],[-.2,.95],[-.02,.95],[.0,.92]].map(([x,z])=>[x,z]),-.0025,.0025,C,.001,1,true);},35,null,M4.basis([X(u0),Y,0],ax,ay,az));}}
  /* the tow strap, looped under the slot */
  {const z=-.26,u=K.uFront(.26,y+.1)+.02,RED=SMC('#c41d16',MAT.FABRIC),path=[];for(let k=0;k<=12;k++){const t=k/12*PI;path.push([X(u)+Math.sin(t)*.045,y+.05-.025*Math.sin(t)-Math.cos(t)*.03,z]);}
    hdPart(out,mb=>{hdSweep(mb,path,[[-.0015,-.012],[.0015,-.012],[.0015,.012],[-.0015,.012]],RED,[0,0,1],true,true);},40);}
}
function hkSkirts(out,car){
  const K=HDK,D=K.D,X=K.X,C=hkCARB(),y=K.dy+D.B.chY+.34,u0=D.uFa+D.arch.a+.1,u1=D.uRa-D.arch.a-.1;
  for(const s of [1,-1]){const rows=[];
    for(let k=0;k<=30;k++){const t=k/30,u=u0+(u1-u0)*t,e=sm01(Math.min(t,1-t)/.08),zb=K.sideZ(u,y+.05)-.01,o=.075*e+.01;
      const sec=[[0,.03],[o*.6,.012],[o,.0],[o+.004,-.012],[o-.004,-.02],[0,-.02]];rows.push(sec.map(([dz,dy2])=>[X(u),y+dy2,s*(zb+dz)]));}
    hdPart(out,mb=>{hdLoft(mb,rows,C,true,s<0);hdCap(mb,rows[0],C,s>0);hdCap(mb,rows[30],C,s<0);},40);}
}
function hkScoop(out,car){
  const K=HDK,D=K.D,G=D.G,X=K.X,PA=SV([1,1,1],MAT.PAINT),u0=G.rf+.08,u1=u0+.42,w=.17,h=.075,n=20,m=16;
  const hh=u=>h*Math.pow(clamp(1-(u-u0)/(u1-u0),0,1),.8),prof=(z,u)=>K.topY(u,Math.abs(z))+hh(u)*Math.pow(Math.max(0,1-Math.pow(Math.abs(z)/w,4)),.5)-.002;
  /* the hood: rows across from side to side, from the mouth back to where it meets the glass */
  const rows=[];for(let i=0;i<=n;i++){const u=u0+(u1-u0)*i/n,row=[];for(let j=0;j<=m;j++){const z=-w*1.06+2*w*1.06*j/m;row.push([X(u),Math.abs(z)>w?K.topY(u,Math.abs(z))-.002:prof(z,u),z]);}rows.push(row);}
  hdPart(out,mb=>{hdLoft(mb,rows,PA,false,true);},45);
  /* the mouth: its lip, a black throat back into the hood, the mesh across it */
  const mouth=[];for(let j=0;j<=m;j++){const z=-w+2*w*j/m;mouth.push([z,prof(z,u0)]);}
  const lipIn=mouth.map(([z,yy])=>[z*.9,K.topY(u0,Math.abs(z))+(yy-K.topY(u0,Math.abs(z)))*.82]);
  hdPart(out,mb=>{const A=mouth.map(([z,yy])=>[X(u0),yy,z]),B=lipIn.map(([z,yy])=>[X(u0)-.004,yy,z]);hdLoft(mb,[A,B],PA,false,true);
    const T=lipIn.map(([z,yy])=>[X(u0+.12),K.topY(u0+.12,Math.abs(z))+(yy-K.topY(u0,Math.abs(z)))*.5,z]);hdLoft(mb,[B,T],HC.GB,false,true);
    const base=[[X(u0)-.004,K.topY(u0,w*.9),-w*.9],[X(u0+.12),K.topY(u0+.12,w*.9),-w*.9],[X(u0+.12),K.topY(u0+.12,w*.9),w*.9],[X(u0)-.004,K.topY(u0,w*.9),w*.9]];
    mb.quad(base[0],base[1],base[2],base[3],HC.GB[0],0,HC.GB[2]);hdCap(mb,T,HC.GB,false);},30);
  {const P=lipIn.map(([z,yy])=>[z,yy]).concat([[w*.9,K.topY(u0,w*.9)],[-w*.9,K.topY(u0,w*.9)]]);
    hdPart(out,mb=>{hpMesh(mb,hdHull(P),.012,.0012,HC.HONEY,([z,yy],l)=>[X(u0+.012+l),yy,z]);},0);}
}
function hkFin(out,car){
  const K=HDK,D=K.D,G=D.G,X=K.X,C=hkCARB(),u0=G.rr-.15,u1=D.L-.4,n=24,base=[],top=[],tR=K.topY(G.rr,0)+.03,t1=K.topY(u1,0);
  for(let i=0;i<=n;i++){const t=i/n,u=u0+(u1-u0)*t;base.push([X(u),K.topY(u,0)-.01]);top.push([X(u),tR-(tR-t1)*.25*Math.pow(t,1.4)]);}
  /* the fin's outline: up the base, back down the top, its leading corner rounded off */
  const poly=base.concat(top.slice().reverse());
  hdPart(out,mb=>{hdExtrude(mb,poly,-.0055,.0055,C,.0025,3,true);},35);
}
function hkWing(out,car){
  const K=HDK,D=K.D,X=K.X,L=D.L,C=hkCARB(),hw=.86,c=.34,yd=K.topY(L-.28,.42),yw=yd+.29,xl=X(L-.44),aoa=.2;
  /* the game's wing off its body (its main plane, Gurney, necks and endplates, all carbon over the tail) */
  hdDrop(car.body,(cc,m)=>m===MAT.CARBON&&D.uC-cc[0]>3.9&&cc[1]>.75);
  /* the main plane: a cambered section, lifted at the back by its angle */
  const sec=[];{const N=18;for(let i=0;i<=N;i++){const t=.5-.5*Math.cos(i/N*PI),th=.11*c*(2.97*Math.sqrt(t)-1.26*t-3.52*t*t+2.84*t*t*t-1.0*t*t*t*t)*.5,cam=-.045*c*4*t*(1-t);sec.push([t,cam+th]);}
    for(let i=N-1;i>=1;i--){const t=.5-.5*Math.cos(i/N*PI),th=.11*c*(2.97*Math.sqrt(t)-1.26*t-3.52*t*t+2.84*t*t*t-1.0*t*t*t*t)*.5,cam=-.045*c*4*t*(1-t);sec.push([t,cam-th]);}}
  const at=(t,v,z)=>{const xx=t*c,ca=Math.cos(aoa),sa=Math.sin(aoa);return [xl-(xx*ca+v*sa*0),yw+xx*sa+v*ca,z];};
  const rings=[];for(let k=0;k<=8;k++){const z=-hw+2*hw*k/8;rings.push(sec.map(([t,v])=>at(t,v,z)));}
  hdPart(out,mb=>{hdLoft(mb,rings,C,true);hdCap(mb,rings[0],C,true);hdCap(mb,rings[8],C,false);},40);
  /* the Gurney strip along the trailing edge */
  {const p=at(1,0,0);hdPart(out,mb=>{hdRBox(mb,[p[0]+.002,p[1]+.012,0],[.002,.014,hw-.005],.0015,C,1);},30);}
  for(const s of [1,-1]){
    /* the endplate */
    hdPart(out,mb=>{hdExtrude(mb,[[xl+.05,yw-.09],[xl+.03,yw+.1],[xl-c-.03,yw+.13],[xl-c-.06,yw-.09]].reverse(),s*hw+(s>0?0:-.008),s*hw+(s>0?.008:0),C,.002,2,true);},35);
    /* the swan neck: up from its foot on the deck behind the wing, over the top and down onto the plane */
    const z=s*.42,top=at(.38,.0,z),yf=K.topY(L-.07,.42),path=[[X(L-.07),yf-.005,z],[X(L-.065),yd+.08,z],[X(L-.07),yw+.08,z],[X(L-.11),yw+.13,z],[X(L-.2),yw+.145,z],[top[0]-.01,top[1]+.06,z],[top[0],top[1]+.012,z]];
    hdPart(out,mb=>{hdSweep(mb,path,[[-.026,-.006],[.026,-.006],[.026,.006],[-.026,.006]],C,[0,0,1],true,true);},35);
    hdPart(out,mb=>{hdRBox(mb,[X(L-.07),yf+.004,z],[.05,.01,.022],.005,C,2);for(const du of [-.03,.03])hdCyl(mb,[X(L-.07+du),yf+.012,z],[X(L-.07+du),yf+.022,z],.006,.006,8,HC.BOLT);},35);
    hdPart(out,mb=>{hdRBox(mb,[top[0],top[1]+.012,z],[.05,.006,.02],.004,C,2);},35);}
}

;
/* =====================================================================================
   THE MUSCLE IN THE STUDIO: the game's own 1970-style V8 fastback (21_suv BODIES.muscle, 28_muscle, the Stock build in
   32_builds: "Big block, four-speed"), built finer, with each part modelled again in this folder, one file a part:
   81 the wheel, 82 the face and front bumper, 83 the tail and rear bumper, 84 the power bulge, 85 the cabin, 87 the
   engine bay. What the game paints on as decals or builds as plain boxes and this folder builds again is left off
   the game's body (skip). The race mirrors are the EV's (79_parts), as the game gives it the same; the handles the
   SUV Studio's in chrome; the side markers and the exhaust are the game's.
   ===================================================================================== */
HD_CARS.muscle={
  skip:{FACES:['muscle'],TAILS:['muscle'],FRONTS:['chrome'],REARS:['chrome'],HOODS:['bulge']},
  build(out){
    const b=out.b,lk=b.look;
    const W=muWheel(lk.tyre);out.wheel=out.wheelR=W.spin;out.brake=out.brakeR=W.fixed;
    const ar=new MB();hdArches(ar,out);out.hd.arches=ar;
    if(typeof muFace==='function'){const f=new MB();muFace(f,out);out.hd.face=f;}
    if(typeof muTail==='function'){const t=new MB();muTail(t,out);out.hd.tail=t;}
    if(typeof muBulge==='function'){const h=new MB();muBulge(h,out);out.hd.hood=h;}
    if(typeof muCabin==='function'){const c=new MB();muCabin(c,out);out.hd.cabin=c;}
    {const t=new MB();hdMirrorsRace(t,out);hdHandles(t,out);hdWipers(t,out);out.hd.trim=t;}
    if(typeof muBay==='function')out.bay=muBay(out);
    out.under=hdUnder(out);
  },
  views:{cabin:D=>{const G=D.G,u=G.pillars[0][0]-.35;return {p:[D.X(u),D.belt(u)+.45,1.6],t:[D.X(G.cowl+.45),D.belt(u)-.2,-.3]};}}
};

;
/* =====================================================================================
   THE MUSCLE'S WHEEL: its 235/60R15 tyre on the 15-inch chrome five-spoke the game gives it (30_wheels 'mag'),
   modelled for a close look. Same axes and size as the game's wheel.
   - The tyre (78_run hdTyre 'hwy').
   - The wheel, in chrome: five slim spokes with tall windows between them, a polished lip, five chrome nuts round a
     small chrome cap.
   - The brake (78_run hdBrake): a small plain rotor and a single-piston caliper, as a 1970 car had.
   ===================================================================================== */
function muWheel(w){
  const spin=new MB(),fixed=new MB();hdTyre(spin,w,{kind:'hwy'});
  const rimR=w.rim*.0254/2,hw=w.W/2,zo=hw*.77,RIMM=SV([1,1,1],MAT.RIM),n=5,face=zo-.03;
  const fz=r=>face+.01+(zo-.004-face-.01)*Math.pow(clamp((r-.07)/(rimR-.07),0,1),1.4);
  hdRimParts(spin,w,{lugs:5,pcd:.1143,face:face+.008,lip:HC.BRUSH,barrel:HC.CAST,lugR:.01,lugH:.022,lugA:PI/5,lugM:MM.CHROME,valveA:PI/n});
  hdPart(spin,mb=>{hdDiscWin(mb,{rIn:.07,rOut:rimR-.006,zAt:fz,m:RIMM,n,r0:.088,r1:.158,frac:.62,phase:.1,thick:.035,na:16,nr:18});},32);
  hdPart(spin,mb=>{hdRev(mb,[[rimR-.006,fz(rimR-.006)],[rimR,zo+.004],[rimR+.006,zo+.008],[rimR+.013,zo+.005]],128,HC.BRUSH);},35);
  /* the hub's flat, the nuts on it, the small chrome cap */
  hdPart(spin,mb=>{hdRev(mb,[[.07,fz(.07)],[.066,face+.008],[.044,face+.008]],64,RIMM,0,TAU,true);},40);
  hdPart(spin,mb=>{hdRev(mb,[[.044,face+.008],[.042,face+.026],[.033,face+.034],[.015,face+.037],[0,face+.0375]],48,MM.CHROME,0,TAU,true);},40);
  hdBrake(spin,fixed,w,{ro:.13,ri:.08,zc:-.022,pistons:1});
  return {spin,fixed,tris:(spin.p.length+fixed.p.length)/9};
}

;
/* =====================================================================================
   THE MUSCLE'S FACE AND FRONT BUMPER, IN THREE DIMENSIONS (in place of 28_muscle FACES.muscle's decals and
   FRONTS.chrome's boxes), on the decals' own outlines:
   - The grille right across the nose: a black opening in a chrome frame, eight black bars across it.
   - The lamps set into its ends: round sealed beams in chrome rings, each a deep reflector, the bulb under its
     chrome cap, a fluted glass.
   - The amber parking lamps low down.
   - The bumper: a thin chrome blade along the nose, wrapping back round the corners, on its black brackets.
   (Swept sections here are [up, out] or [out, up], as each says.)
   ===================================================================================== */
function muFace(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,cuts=[car.body,car.hood];
  /* ---------- the grille ---------- */
  {const G0=RR2(-.875,.875,Y(.445),Y(.675),.03);for(const c of cuts)hdCut(c,'F',G0);
    hdRecess(out,'F',G0,.08,.98,HC.GB,()=>HC.GB);
    hdTrim(out,'F',hdResample(G0,.008),.018,.007,MM.CHROME,true,50);
    for(let k=0;k<8;k++){const yc=Y(.476+k*.024),h=.006,path=[];for(let z=-.63;z<=.6301;z+=.02)path.push(hdS('F',z,yc,-.02));
      hdPart(out,mb=>{hdSweep(mb,path,[[-h,-.014],[-h*.8,.003],[0,.005],[h*.8,.003],[h,-.014]],HC.PLASTIC,[1,0,0],true,true);},40);}}
  /* ---------- the lamps in the grille's ends ---------- */
  for(const s of [1,-1]){const c0=[s*.755,Y(.56)];
    hdLampUnit(out,'F',EL2(c0[0],c0[1],.072,.072,48),[],{deep:.09,k:.72,wall:HC.REFLC,back:()=>HC.REFLC,bulge:.01,cell:.005,lens:()=>HC.LENSH,seal:false,
      inside:o=>{const b=hdS('F',c0[0],c0[1],-.055);hdPart(o,mb=>{ball(mb,b,.011,16,HC.LAMPH);},50);
        hdRevAt(o,'F',V3.add(b,[.014,0,0]),[[.022,-.004],[.021,.003],[.014,.007],[0,.008]],MM.CHROME,24);}});
    hdPart(out,mb=>{for(let z=-.063;z<=.0631;z+=.0105){const h=Math.sqrt(Math.max(0,.069*.069-z*z));if(h<.018)continue;const p=[];for(let y=-h;y<=h+1e-6;y+=.01)p.push(hdS('F',c0[0]+z,c0[1]+y,-.0006+.01*(1-(z*z+y*y)/(.072*.072))));
      hdSweep(mb,p,[[-.0022,0],[0,.001],[.0022,0]],HC.LENSH,[1,0,0],false,true);}},40);
    hdRevAt(out,'F',hdS('F',c0[0],c0[1],.004),[[.088,-.002],[.087,.005],[.082,.009],[.075,.01],[.0725,.006],[.072,0]],MM.CHROME,72);
    /* ---------- the amber parking lamp ---------- */
    hdLampUnit(out,'F',RR2(s*.66,s*.78,Y(.272),Y(.31),.008),[car.body],{deep:.035,k:.88,wall:HC.GB,back:()=>HC.REFLC,bulge:.003,cell:.004,lens:()=>HC.AMBERL,tol:.05,
      inside:o=>{hdPart(o,mb=>{ball(mb,hdS('F',s*.72,Y(.291),-.02),.007,12,HC.BULB);},50);}});}
  muBumperF(out,car);
}
/* a chrome blade bumper along a plan [x, z] (from one end to the other) at height y: its section [out, up] */
function muBlade(out,plan,y,o={}){const sec=hdRRect(o.d||.035,o.h||.034,o.r||.016,5).map(([a,b])=>[a,b]);
  const path=plan.map(([x,z])=>[x,y,z]);hdPart(out,mb=>{hdSweep(mb,path,sec,MM.CHROME,[0,1,0],true,true);},40);}
function muBumperF(out,car){
  const K=HDK,D=K.D,X=K.X,dy=K.dy,Y=y=>y+dy,x0=X(0)-.005,y=Y(.4),plan=[];
  /* the plan: straight across, then round the corners and back along the fenders, as the game's bar and its ends */
  for(let k=0;k<=28;k++){const t=k/28,z=-.97+1.94*t,az=Math.abs(z),back=az<.8?0:Math.pow((az-.8)/.17,1.6)*.26;plan.push([x0-back,z]);}
  muBlade(out,plan,y);
  /* its brackets behind, to the frame */
  for(const s of [1,-1])hdPart(out,mb=>{hdRBox(mb,[x0-.08,y,s*.55],[.06,.02,.025],.006,SMC('#1a1a1c',SM.PAINTED),2);},35);
}

;
/* =====================================================================================
   THE MUSCLE'S TAIL AND REAR BUMPER, IN THREE DIMENSIONS (in place of 28_muscle TAILS.muscle's decals and
   REARS.chrome's boxes), on the decals' own outlines:
   - The black panel right across the tail; in it two wide lamps in chrome bezels, each a red lens over a reflector
     with two chrome bars across it, its bulbs behind.
   - The deck lid's shut lines across the deck and down its sides (the game's outlines).
   - The plate below the bumper, on its black bracket, with its lamp.
   - The bumper: the thin chrome blade, wrapping forward round the corners.
   ===================================================================================== */
function muTail(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,X=K.X,cuts=[car.body];
  /* ---------- the panel and its lamps ---------- */
  {const P0=RR2(-.9,.9,Y(.485),Y(.655),.02);for(const c of cuts)hdCut(c,'R',P0,.04);hdRecess(out,'R',P0,.014,.995,HC.GB,()=>SV([.012,.012,.014],SM.PLASTIC),4);}
  for(const s of [1,-1]){const Lp=RR2(Math.min(s*.212,s*.853),Math.max(s*.212,s*.853),Y(.512),Y(.628),.025);
    hdLampUnit(out,'R',Lp,[],{deep:.06,k:.92,wall:HC.GB,back:()=>HC.REFLC,bulge:.003,cell:.005,lens:()=>HC.REDL,seal:false,tol:.04,
      inside:o=>{hdPart(o,mb=>{for(let y=.522;y<.62;y+=.012)hdCyl(mb,hdS('R',s*.23,Y(y),-.045),hdS('R',s*.835,Y(y),-.045),.0022,.0022,6,HC.REFLC,false);},30);
        for(const z of [.36,.53,.7]){hdRevAt(o,'R',hdS('R',s*z,Y(.57),-.058),[[.032,.014],[.027,.006],[.015,.001],[0,0]],HC.REFLC,28);hdPart(o,mb=>{ball(mb,hdS('R',s*z,Y(.57),-.044),.0075,14,HC.BULB);},50);}}});
    /* the chrome bezel round it, the two bars across it */
    hdTrim(out,'R',hdResample(RR2(Math.min(s*.2,s*.865),Math.max(s*.2,s*.865),Y(.5),Y(.64),.03),.008),.014,.006,MM.CHROME,true,50,-.012);
    for(const y of [.556,.59]){const p=[];for(let z=.215;z<=.8501;z+=.02)p.push([s*z,Y(y)]);hdTrim(out,'R',p,.006,.004,MM.CHROME,false,50,.003);}}
  /* ---------- the deck lid's shut lines ---------- */
  {const deck=(pts)=>hdPart(out,mb=>{hdSweep(mb,pts,[[-.0025,-.001],[.0025,-.001],[.0025,.0006],[-.0025,.0006]],HC.GB,[0,1,0],true,true);},50);
    {const p=[];for(let z=-.62;z<=.6201;z+=.02)p.push(hdTS(4.28,z,.0002));deck(p);}
    for(const s of [1,-1]){const p=[];for(let t=0;t<=1.0001;t+=.05){const u=4.28+(D.L-.08-4.28)*t;p.push(hdTS(u,s*(.62+.08*t),.0002));}deck(p);}}
  /* ---------- the plate below the bumper ---------- */
  {const x=X(D.L)+.03,y=Y(.3375),BR=SMC('#1a1a1c',SM.PAINTED);
    hdPart(out,mb=>{hdRBox(mb,[x+.012,y+.01,0],[.008,.06,.17],.006,BR,2);},35);
    hdPart(out,mb=>{hdRBox(mb,[x,y,0],[.003,.0375,.155],.004,SV([1,1,1],MAT.PLATE),2);},30);
    hdPart(out,mb=>{const r=hdResample(RR2(-.15,.15,y-.033,y+.033,.006),.01).map(([z,yy])=>[x-.0032,yy,z]);r.push(r[0]);hdTube(mb,r,.0015,6,SV([.05,.07,.18],MAT.COL),false,false);},40);
    hdPart(out,mb=>{hdRBox(mb,[x-.004,y+.05,0],[.006,.008,.03],.004,HC.LENS,2);},40);}
  muBumperR(out,car);
}
function muBumperR(out,car){
  const K=HDK,D=K.D,X=K.X,dy=K.dy,Y=y=>y+dy,x=X(D.L)+.005,y=Y(.45),plan=[];
  for(let k=0;k<=28;k++){const t=k/28,z=-.98+1.96*t,az=Math.abs(z),fwd=az<.8?0:Math.pow((az-.8)/.18,1.6)*.27;plan.push([x+fwd,z]);}
  muBlade(out,plan,y);
  for(const s of [1,-1])hdPart(out,mb=>{hdRBox(mb,[x+.08,y,s*.55],[.06,.02,.025],.006,SMC('#1a1a1c',SM.PAINTED),2);},35);
}

;
/* =====================================================================================
   THE MUSCLE'S POWER BULGE (in place of 28_muscle HOODS.bulge, the same shape drawn finer: forty steps along it
   instead of ten, twenty-four across instead of six): a raised panel up the middle of the bonnet, rising quickly
   behind its front lip and falling away toward the windshield, its sides rounding down into the bonnet. Built on
   the bonnet, so it lifts with it.
   ===================================================================================== */
function muBulge(out,car){
  const K=HDK,D=K.D,X=K.X,topY=D.topY,u0=.42,u1=1.25,n=40,m=24,w=.2,PA=SV([1,1,1],MAT.PAINT);
  /* (the game's height: up to five centimetres, full a tenth of the way back, easing off toward the back) */
  const h=u=>{const t=(u-u0)/(u1-u0);return .05*Math.min(1,t*8+.15)*(1-.3*t);};
  const rows=[];for(let i=0;i<=n;i++){const u=u0+(u1-u0)*i/n,row=[];
    for(let k=0;k<=m;k++){const q=-1+2*k/m,z=q*(w+.02),edge=Math.abs(q)>w/(w+.02)?(Math.abs(q)-w/(w+.02))/(1-w/(w+.02)):0,
        c=Math.pow(Math.cos(Math.min(1,Math.abs(q)*(w+.02)/w)*PI/2),.35),lift=h(u)*(edge>0?0:c)+.0015;
      row.push([X(u),topY(u,Math.abs(z))+lift,z]);}
    rows.push(row);}
  hdPart(out,mb=>{for(let i=0;i<n;i++)for(let k=0;k<m;k++)mb.quad(rows[i][k],rows[i+1][k],rows[i+1][k+1],rows[i][k+1],PA[0],0,PA[2]);},40);
  /* its front lip: the face from the bonnet up to the bulge's leading edge */
  hdPart(out,mb=>{const f=rows[0];for(let k=0;k<m;k++){const a=f[k],b=f[k+1];mb.quad([a[0]+.0005,topY(u0,Math.abs(a[2]))-.002,a[2]],[b[0]+.0005,topY(u0,Math.abs(b[2]))-.002,b[2]],b,a,PA[0],0,PA[2]);}},30);
}

;
/* =====================================================================================
   THE MUSCLE'S CABIN (79_cabin hdCabinGen, the SUV Studio's way): a 1970 big-block coupe's, in black vinyl. A long
   flat dash with a hood over two big dials (the speed and the tachometer) and two small; a thin three-spoke wheel
   with chrome spokes; the four-speed's chrome stick in the console, a white ball on it; two low buckets, a bench
   behind without headrests (the fastback's roof comes down over it); door panels with window winders.
   ===================================================================================== */
function muCabin(out,car){
  const D=HDK.D,G=D.G,pil=G.pillars.map(p=>p[0]);
  hdCabinGen(out,car,{floorY:.27+D.dy,uEnd:pil[0]+.6,headEnd:G.rr+.1,doors:2,armY:.27,dashDepth:.46,dashTop:D.belt(G.cowl+.46)-.04,hoodH:.04,
    dials:[[-.075,.055,0],[.075,.055,0],[-.18,.028,0],[.18,.028,0]],clusterW:.24,vents:[-.62,-.2,.2,.62],stackW:.16,needle:'#f2efe6',
    wheelU:.18,wheelDrop:.1,wheelR:.2,rimT:.013,spokes:[0,PI,-PI/2],spokeT:.008,spokeM:MM.CHROME,hub:[.05,.055,.03],
    shifter:'manual',knob:SMC('#ecebe6',SM.WHITE),console:'small',consoleBack:.25,winders:1,
    seatF:pil[0]-.4,seatY:.15,seatZ:.38,seatW:.52,bolster:1,rear:'bench',seatR:pil[0]+.2,seatYR:.17,rearHead:0,rearW:1.3,back:'parcel',parcel:[pil[0]+.48,G.rr+.62,D.belt(pil[0]+.6)+.02],
    tunnel:.13,toe:.2,tunnelEnd:pil[0]+.2,
    col:{dash:'#1b1b1d',dashTop:'#151516',vinyl:'#1f1f21',insert:'#2a2a2d',head:'#2b2b2d',carpet:'#1c1c1e',seat:'#1e1e20',seatSide:'#19191b'}});
}

;
/* =====================================================================================
   THE MUSCLE'S ENGINE BAY (79_bay hdBayGen): the factory 7.0 big-block V8 (the game's bb72, 16_engines) lengthways
   against the firewall, in the game's colours for it: a blue block and heads, polished valve covers. A 1970 engine,
   so no plenum and no airbox: a four-barrel carburettor on a cast intake under a big round chrome air cleaner, plug
   leads to the distributor at the back; a mechanical fan in its shroud.
   ===================================================================================== */
function muBay(car){return hdBayGen(car,{engine:{layout:'V8',carb:1,polish:1,block:'#2b4796',head:'#2b4796',cover:'#c9ccd1'},tubeR:.05});}

;
/* =====================================================================================
   THE PICKUP IN THE STUDIO: the game's own crew cab (21_suv BODIES.pickup, 27_pickup, the Stock build in 32_builds:
   "Off-road trim from the dealer"), built finer, with each part modelled again in this folder, one file a part:
   81 the wheel, 82 the face and front bumper, 83 the tail and step bumper, 84 the bed, 85 the cabin, 86 the bolt-ons
   (mirrors, handles, running boards, wipers), 87 the engine bay. What the game paints on as decals or builds as plain
   boxes and this folder builds again is left off the game's body (skip).
   ===================================================================================== */
HD_CARS.pickup={
  skip:{FACES:['pickup'],TAILS:['pickup'],FRONTS:['pickup'],REARS:['pickup'],EXTRAS:['steps']},
  build(out){
    const b=out.b,lk=b.look;
    /* the wheel: what turns, and the brake's caliper and shield, which only steer */
    const W=pkWheel(lk.tyre);out.wheel=out.wheelR=W.spin;out.brake=out.brakeR=W.fixed;
    /* the wheel houses and flares (73_arch, the SUV's), the underside apart */
    const ar=new MB();hdArches(ar,out);out.hd.arches=ar;const fl=new MB();hdFlares(fl);out.hd.flares=fl;
    if(typeof pkFace==='function'){const f=new MB();pkFace(f,out);out.hd.face=f;}
    if(typeof pkTail==='function'){const t=new MB();pkTail(t,out);out.hd.tail=t;}
    if(typeof pkBed==='function'){const t=new MB();pkBed(t,out);out.hd.bed=t;}
    if(typeof pkCabin==='function'){const c=new MB();pkCabin(c,out);out.hd.cabin=c;}
    {const t=new MB();hdMirrors(t,out);hdHandles(t,out);hdWipers(t,out);pkSteps(t,out);pkFuel(t,out);out.hd.trim=t;}
    if(typeof pkBay==='function')out.bay=pkBay(out);
    out.under=hdUnder(out);
  },
  /* the cabin seen in through the passenger's window, the dash and the wheel beyond; the bed from over the tailgate */
  views:{cabin:D=>{const G=D.G,u=G.pillars[0][0]-.05;return {p:[D.X(u),D.belt(u)+.55,1.75],t:[D.X(G.cowl+.4),D.belt(u)-.22,-.35]};},
    bed:D=>({p:[D.X(D.L)-1.6,2.7,1.2],t:[D.X(D.B.bed+.9),1.1,0]})}
};

;
/* =====================================================================================
   THE PICKUP'S WHEEL: its 285/70R18 all-terrain on the factory 18-inch six-spoke, in the dark grey the game paints
   it (the build's rim colour), modelled for a close look. Same axes and size as the game's wheel.
   - The tyre (78_run hdTyre 'at'): chunky staggered blocks either side of a zig-zag centre, a sipe or two in every
     block, stone ejectors, the stepped shoulder blocks and the lugs down the sidewall, long and short in turn.
   - The wheel: six broad spokes, each with a machined channel down its middle, drafted sides, dished out to a
     painted lip; a raised hub face, six chrome lug nuts on a 139.7 mm circle in dark seats, a big gloss black cap.
   - The brake (78_run hdBrake): a 340 mm vented rotor that turns with the wheel; a twin-piston caliper, its bracket
     and the dust shield on a piece of their own that only steers.
   ===================================================================================== */
function pkWheel(w){
  const spin=new MB(),fixed=new MB(),T=hdTyre(spin,w,{kind:'at'}),RIMC=SV([1,1,1],MAT.RIM),hw=w.W/2,face=hw*.77-.038;
  const P=hdRimParts(spin,w,{lugs:6,pcd:.1397,face,lip:RIMC,barrel:HC.CAST,lugR:.0118,lugH:.027,valveA:0});
  const rimR=P.rimR,zo=P.zo;
  /* six spokes: lofted out along the radius, dished from the hub to the lip, a channel down the middle of each */
  hdPart(spin,mb=>{const r0=.088,r1=rimR-.011,n=22;
    for(let k=0;k<6;k++){const a=k/6*TAU+PI/6,ca=Math.cos(a),sa=Math.sin(a),tx=-sa,ty=ca;const rings=[];
      for(let i=0;i<=n;i++){const t=i/n,r=r0+(r1-r0)*t,zf=face+(zo-.004-face)*Math.pow(t,1.5),wt=.07+.05*Math.pow(t,1.1)+.016*sm01((t-.84)/.16),d=.034,ch=.0035*sm01(t/.12)*sm01((1-t)/.12);
        const sec=[[-wt/2-.007,zf-d],[-wt/2-.002,zf-.006],[-wt/2+.002,zf-.0012],[-wt*.3,zf+.0014],[-wt*.17,zf+.0016],[-wt*.13,zf+.0016-ch],[wt*.13,zf+.0016-ch],[wt*.17,zf+.0016],[wt*.3,zf+.0014],[wt/2-.002,zf-.0012],[wt/2+.002,zf-.006],[wt/2+.007,zf-d]];
        rings.push(sec.map(([u,z])=>[ca*r+tx*u,sa*r+ty*u,z]));}
      hdLoft(mb,rings,RIMC,false);}
  },30,[0,0,-.2]);
  /* the hub face: raised, chamfered down into the spokes; the cap's ring */
  hdPart(spin,mb=>{hdRev(mb,[[0,face+.009],[.052,face+.009],[.056,face+.0075],[.086,face+.001],[.098,face-.004],[.102,face-.022]],96,RIMC,0,TAU,true);},30);
  hdPart(spin,mb=>{hdRev(mb,[[.05,face+.009],[.0495,face+.018],[.046,face+.025],[.034,face+.031],[.016,face+.0335],[0,face+.034]],64,HC.GB,0,TAU,true);},50);
  hdPart(spin,mb=>{hdRev(mb,[[.0515,face+.0088],[.0515,face+.012],[.0498,face+.0135]],64,MM.CHROME,0,TAU,true);},50);
  hdBrake(spin,fixed,w,{ro:.17,ri:.104,zc:-.03,pistons:2});
  return {spin,fixed,tris:(spin.p.length+fixed.p.length)/9};
}

;
/* =====================================================================================
   THE PICKUP'S FACE AND FRONT BUMPER, IN THREE DIMENSIONS. The game paints its face on as decals (27_pickup
   FACES.pickup) and builds its bumper from boxes (FRONTS.pickup); here the body is cut open where each one sits and
   the real thing is built in the hole, on the decals' own outlines and sizes, so it is the same face.
   - The grille: the big opening, deep and dark; the thick body-colour surround standing out of it on a moulded
     section; a black inner frame; the honeycomb set back in it, big cells, deep walls.
   - The headlamps: square, in a cavity with chrome reflectors and satin walls; two projectors (chrome bezel,
     reflector bowl, barrel, the lens) on a black bezel panel; the LED brow across the bottom in its black channel;
     the amber corner behind a chrome divider with its bulb; one clear lens over it all, amber over the corner.
   - The bumper: one moulding in black textured plastic, lofted along its plan: the bar, the corners wrapping back to
     the flares, the valance under it with the intake and its slats; fog lamps in pockets (bezel, reflector, bulb,
     lens); the red tow hooks; the aluminium skid plate under it with its slots and bolts.
   ===================================================================================== */
function pkFace(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,cuts=[car.body,car.hood],X=K.X;
  /* ---------- the grille ---------- */
  const G0=RR2(-.69,.69,Y(.835),Y(1.315),.035);
  for(const c of cuts)hdCut(c,'F',G0);
  hdRecess(out,'F',G0,.1,.975,HC.GB,()=>HC.GB);
  /* the body-colour surround: a thick moulded frame, its outer edge clear of the opening's edge (the black gap), its
     inner side dropping into the opening */
  {const path=hdResample(RR2(-.627,.627,Y(.872),Y(1.278),.032),.008).map(p=>hdS('F',p[0],p[1],0));path.push(path[0]);
    const sec=[[-.041,-.03],[-.041,-.004],[-.038,.011],[-.031,.019],[-.02,.0225],[.024,.0225],[.033,.018],[.039,.008],[.041,-.012],[.041,-.045],[0,-.05]];
    hdPart(out,mb=>{hdSweep(mb,path,sec,MM.PAINT,[1,0,0],true,false);},40);}
  /* the black inner frame, and the honeycomb behind it */
  hdTrim(out,'F',hdResample(RR2(-.578,.578,Y(.893),Y(1.247),.02),.01),.014,.006,HC.GB,true,50,-.035);
  hdHoney(out,'F',RR2(-.57,.57,Y(.898),Y(1.243),.016),.048,.034,.0034,.024,HC.HONEY);
  /* ---------- the headlamps ---------- */
  for(const s of [1,-1]){
    const L=RR2(s*.70,s*.925,Y(.965),Y(1.255),.018);
    hdLampUnit(out,'F',L,cuts,{deep:.095,k:.9,wall:HC.SATIN,back:()=>HC.REFLC,bulge:.005,
      lens:(z,y)=>Math.abs(z)>.853?HC.AMBERL:HC.LENSH,
      inside:o=>{
        /* the black bezel panel the projectors sit in, the reflector above and below them */
        hdPart(o,mb=>{hdGrid(mb,'F',RR2(s*.708,s*.85,Y(1.06),Y(1.245),.014),()=>-.058,()=>HC.GB,.012);},30);
        for(const zp of [.745,.815]){const z=s*zp,y=Y(1.152),b=hdS('F',z,y,-.044),k=.56;
          hdRevAt(o,'F',b,[[.062,-.03],[.06,.004],[.056,.0105],[.05,.012],[.046,.008],[.044,0]].map(([r,h])=>[r*k,h*k]),MM.CHROME,56);
          hdRevAt(o,'F',b,[[.044,0],[.04,-.012],[.032,-.022],[.02,-.028],[0,-.03]].map(([r,h])=>[r*k,h*k]),HC.REFLC,56);
          hdRevAt(o,'F',b,[[.031,-.02],[.031,.012],[.029,.016]].map(([r,h])=>[r*k,h*k]),HC.SATIN,40);
          hdRevAt(o,'F',b,[[.029,.016],[.027,.026],[.02,.035],[.01,.039],[0,.04]].map(([r,h])=>[r*k,h*k]),HC.LAMPH,40,60);}
        /* the LED brow: a light guide in a black channel along the bottom */
        hdPart(o,mb=>{hdGrid(mb,'F',RR2(s*.712,s*.852,Y(.976),Y(1.04),.012),()=>-.034,()=>HC.GB,.01);},30);
        {const path=[];for(let z=.722;z<=.8441;z+=.01)path.push(hdS('F',s*z,Y(1.008),-.024));
          hdPart(o,mb=>{const sec=[];for(let i=0;i<16;i++){const a=i/16*TAU;sec.push([Math.cos(a)*.0105,Math.sin(a)*.0095]);}hdSweep(mb,path,sec,HC.LAMPH,[1,0,0],true,true);},40);}
        /* the amber corner: a chrome divider, a bulb in an amber-backed reflector */
        {const p=[];for(let y=.975;y<=1.2451;y+=.01)p.push([s*.853,Y(y)]);hdTrim(o,'F',p,.006,.075,MM.CHROME,false,50,-.08);}
        {const b=hdS('F',s*.886,Y(1.11),-.064);hdPart(o,mb=>{ball(mb,b,.0085,14,HC.BULB);},50);
          hdRevAt(o,'F',hdS('F',s*.886,Y(1.11),-.075),[[.03,-.006],[.024,-.012],[.012,-.016],[0,-.017]],HC.REFLC,36);}
      }});
  }
  pkBumperF(out,car);
}
/* the front bumper (in place of FRONTS.pickup's boxes): a moulding lofted along its plan, with holes where the fog
   lamps and the intake go */
function pkBumperF(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,X=K.X,xf=X(0)+.085,CL=SV([1,1,1],MAT.CLAD);
  /* the plan, right half: the bar straight across, a corner radius, then back along the side to the flare */
  const half=[];for(let z=0;z<=.86;z+=.02)half.push([xf-.012*(z/.86)**2,z]);
  const rc=.12,cx=xf-.012-rc;for(let k=1;k<=16;k++){const a=k/16*PI/2;half.push([cx+Math.cos(a)*rc,.86+Math.sin(a)*rc]);}
  for(let x=cx-.03;x>=X(.26);x-=.03)half.push([x,.98-.004*(cx-x)]);
  const plan=[...half.slice(1).reverse().map(([x,z])=>[x,-z]),...half];
  /* the section, from the top's back edge over the bar, down its face, under it, and the valance below (q: how far
     back from the plan, y) */
  const sec=[[.13,Y(.834)],[.06,Y(.836)],[.026,Y(.833)],[.009,Y(.826)],[.0015,Y(.81)],[.0002,Y(.777)],[0,Y(.745)],[.0004,Y(.713)],[.002,Y(.69)],[.006,Y(.66)],[.012,Y(.637)],[.022,Y(.626)],[.034,Y(.62)],
    [.036,Y(.611)],[.034,Y(.604)],[.0345,Y(.566)],[.037,Y(.528)],[.041,Y(.52)],[.052,Y(.514)],[.072,Y(.507)],[.15,Y(.503)]];
  /* every station: the point on the plan and the way back (into the car) there */
  const st=plan.map((p,i)=>{const a=plan[Math.max(0,i-1)],b=plan[Math.min(plan.length-1,i+1)],tx=b[0]-a[0],tz=b[1]-a[1],l=Math.hypot(tx,tz)||1;return {p,n:[-tz/l,tx/l]};});
  /* (the way back is the plan's inward side: on the bar, -x) */
  for(const s of st){const cx2=xf-1.2;if(s.n[0]*(cx2-s.p[0])+s.n[1]*(0-s.p[1])<0){s.n[0]=-s.n[0];s.n[1]=-s.n[1];}}
  const P=(i,j)=>{const s=st[i],[q,y]=sec[j];return [s.p[0]+s.n[0]*q,y,s.p[1]+s.n[1]*q];};
  const fogZ=[.745,.855],fogY=[Y(.713),Y(.777)],inZ=.5,inY=[Y(.528),Y(.604)];
  const hole=(z,y)=>{const a=Math.abs(z);return a>fogZ[0]&&a<fogZ[1]&&y>fogY[0]&&y<fogY[1]||a<inZ&&y>inY[0]&&y<inY[1];};
  hdPart(out,mb=>{for(let i=0;i<st.length-1;i++)for(let j=0;j<sec.length-1;j++){const a=P(i,j),b=P(i+1,j),c=P(i+1,j+1),d=P(i,j+1),zm=(a[2]+c[2])/2,ym=(a[1]+c[1])/2;
      if(hole(zm,ym))continue;mb.quad(a,b,c,d,CL[0],CL[1],CL[2]);}
    /* the ends, closed */
    for(const i of [0,st.length-1])for(let j=1;j<sec.length-1;j++)mb.tri(P(i,0),P(i,j),P(i,j+1),CL[0],CL[1],CL[2]);},38);
  /* the face's point at (z, y) on the bar (its plan and section), pushed back by d */
  const onBar=(z,y,d=0)=>{let i=0;while(i<st.length-1&&st[i+1].p[1]<z)i++;const t=clamp((z-st[i].p[1])/Math.max(1e-6,st[i+1].p[1]-st[i].p[1]),0,1),x0=st[i].p[0]+(st[i+1].p[0]-st[i].p[0])*t;
    let j=0;while(j<sec.length-1&&!(sec[j][1]>=y&&sec[j+1][1]<=y))j++;const u=clamp((sec[j][1]-y)/Math.max(1e-6,sec[j][1]-sec[j+1][1]),0,1),q=sec[j][0]+(sec[j+1][0]-sec[j][0])*u;return [x0-q-d,y,z];};
  /* ---------- the fog lamps: a pocket in the bar, a black bezel, a reflector, the bulb, the lens ---------- */
  for(const s of [1,-1]){const z0=s*fogZ[0],z1=s*fogZ[1],y0=fogY[0],y1=fogY[1],zc=(z0+z1)/2,yc=(y0+y1)/2;
    const rim=[];for(const [z,y] of hdResample(RR2(Math.min(z0,z1),Math.max(z0,z1),y0,y1,.012),.006))rim.push([z,y]);
    hdPart(out,mb=>{const F=rim.map(([z,y])=>onBar(z,y,-.001)),B=rim.map(([z,y])=>onBar(zc+(z-zc)*.86,yc+(y-yc)*.8,.05));hdLoft(mb,[F,B],HC.GB,true);
      const c=onBar(zc,yc,.05);hdCap(mb,B,HC.REFLC,s<0);},30);
    const c=onBar(zc,yc,.03);
    hdPart(out,mb=>{const sh=hdResample(RR2(-.05,.05,-.026,.026,.01),.006),ring=(d,k)=>sh.map(([a,b])=>[c[0]+d,c[1]+b*k,c[2]+a*k]);
      hdLoft(mb,[ring(.026,1.04),ring(.03,1.0),ring(.022,.94)],MM.CHROME,true);},40);
    hdPart(out,mb=>{ball(mb,[c[0]-.006,c[1],c[2]],.009,14,HC.LAMPH);},50);
    hdPart(out,mb=>{const sh=hdResample(RR2(-.047,.047,-.024,.024,.009),.006);const cen=[c[0]+.026,c[1],c[2]];
      for(let i=0;i<sh.length;i++){const a=sh[i],b=sh[(i+1)%sh.length];mb.tri(cen,[cen[0],c[1]+a[1],c[2]+a[0]],[cen[0],c[1]+b[1],c[2]+b[0]],HC.LENSH[0],0,HC.LENSH[2]);}},40);}
  /* ---------- the intake: a dark recess, a lip round it, five slats ---------- */
  {const rim=hdResample(RR2(-inZ,inZ,inY[0],inY[1],.01),.01);
    hdPart(out,mb=>{const F=rim.map(([z,y])=>onBar(z,y,-.001)),B=rim.map(([z,y])=>onBar(z*.99,y,.05));hdLoft(mb,[F,B],HC.GB,true);hdCap(mb,B,HC.GB,false);},30);
    for(let k=0;k<5;k++){const y=inY[0]+(inY[1]-inY[0])*(k+.5)/5,path=[];for(let z=-inZ+.005;z<=inZ-.0049;z+=.02)path.push(onBar(z,y,.012));
      hdPart(out,mb=>{hdSweep(mb,path,[[-.004,-.007],[.004,-.007],[.006,.004],[-.002,.008]].map(([a,b])=>[b,a]),CL,[0,1,0],true,true);},40);}}
  /* ---------- the tow hooks: red J-hooks out of the bar's underside, bolted to a black plate ---------- */
  for(const s of [1,-1]){const z=s*.45,RED=SV(lin('#c8241c'),SM.PAINTED);
    const P0=[xf-.1,Y(.632),z],pts=[P0,[xf-.02,Y(.63),z],[xf+.012,Y(.627),z]];for(let k=1;k<=12;k++){const a=k/12*PI*1.12;pts.push([xf+.012+Math.sin(a)*.03,Y(.597)+Math.cos(a)*.03,z]);}
    hdPart(out,mb=>{hdTube(mb,pts,.0105,14,RED,false,true);},40);
    hdPart(out,mb=>{hdRBox(mb,[xf-.08,Y(.632),z],[.04,.008,.035],.004,HC.GB,2);for(const dz of [-.02,.02])hdCyl(mb,[xf-.095,Y(.6405),z+dz],[xf-.095,Y(.646),z+dz],.007,.007,6,HC.BOLT);},40);}
  /* ---------- the skid plate: brushed aluminium, its front edge turned up, five slots, bolts along the back ---------- */
  {const c=[X(.18),Y(.48),0],ax=V3.norm([1,.4,0]),ay=V3.norm([-.4,1,0]),az=[0,0,1],hl=.2,hw=.46,th=.006,BR=HC.BRUSH;
    const at=(a,w,h)=>V3.add(c,V3.add(V3.mul(ax,a),V3.add(V3.mul(az,w),V3.mul(ay,h))));
    /* (in strips: behind the slots and in front of them plain; across the slots a tile round each, its surface lofted
       from the tile's edge in to the slot's) */
    const as=hl-.07,a0=as-.045,a1=as+.045,face=(mb,q)=>{for(const h of [th/2,-th/2]){const v=q.map(([a,w])=>at(a,w,h));if(h>0)mb.quad(v[0],v[1],v[2],v[3],BR[0],0,BR[2]);else mb.quad(v[0],v[3],v[2],v[1],BR[0],0,BR[2]);}};
    hdPart(out,mb=>{const strip=(aa,ab,n)=>{for(let j=0;j<n;j++){const w0=-hw+2*hw*j/n,w1=-hw+2*hw*(j+1)/n;face(mb,[[aa,w0],[ab,w0],[ab,w1],[aa,w1]]);}};
      strip(-hl,a0,24);strip(a1,hl,24);for(const [w0,w1] of [[-hw,-.4],[.4,hw]])face(mb,[[a0,w0],[a1,w0],[a1,w1],[a0,w1]]);
      for(let k=-2;k<=2;k++){const wc=k*.16,N=40,edge=[],ell=[];
        for(let i=0;i<N;i++){const t=i/N*TAU,cx=Math.cos(t),sx=Math.sin(t),ka=Math.abs(sx)>1e-9?.045/Math.abs(sx):1e9,kw=Math.abs(cx)>1e-9?.08/Math.abs(cx):1e9,kk=Math.min(ka,kw);
          edge.push([as+sx*kk,wc+cx*kk]);ell.push([as+sx*.02,wc+cx*.05]);}
        for(let i=0;i<N;i++){const i1=(i+1)%N;face(mb,[edge[i],edge[i1],ell[i1],ell[i]]);}
        const top=ell.map(([a,w])=>at(a,w,th/2)),bot=ell.map(([a,w])=>at(a,w,-th/2));hdLoft(mb,[top,bot],BR,true);}
      /* the edges, and the front turned up */
      const E=[[-hl,-hw],[hl,-hw],[hl,hw],[-hl,hw]];for(let e=0;e<4;e++){const [p0,w0]=E[e],[p1,w1]=E[(e+1)%4];mb.quad(at(p0,w0,th/2),at(p1,w1,th/2),at(p1,w1,-th/2),at(p0,w0,-th/2),BR[0],0,BR[2]);}
      const lip=(h)=>[at(hl,-hw,h),at(hl,hw,h),at(hl+.04,hw,h+.03),at(hl+.04,-hw,h+.03)];const A=lip(th/2),B=lip(-th/2);mb.quad(A[0],A[1],A[2],A[3],BR[0],0,BR[2]);mb.quad(B[0],B[3],B[2],B[1],BR[0],0,BR[2]);},30);
    hdPart(out,mb=>{for(let k=-4;k<=4;k++){const p=at(-hl+.03,k*.1,th/2);hdCyl(mb,p,V3.add(p,V3.mul(ay,.006)),.008,.0075,6,HC.BOLT);}},40);}
}

;
/* =====================================================================================
   THE PICKUP'S TAIL, IN THREE DIMENSIONS (in place of TAILS.pickup's decals and REARS.pickup's boxes):
   - The tall lamps on the bed's corner posts: a cavity behind each, chrome reflector ribs and bulbs in its two red
     parts, a clear reversing window between them behind a black divider, the red lens and the clear lens over them
     following the corner, a black seal round it.
   - The tailgate: a real shut gap down both sides and along the bottom, the handle in its pocket with a lock.
   - The step bumper: one moulding along its plan, the step on top with a ribbed rubber pad, the plate in a recess
     with its lamps over it and a plain plate (no lettering), the hitch receiver under it with its pin and clip.
   - The third brake lamp on the cab's roof edge, red, with the two cargo lamps either side of it.
   ===================================================================================== */
function pkTail(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,X=K.X,L=D.L,cuts=[car.body];
  /* ---------- the lamps ---------- */
  for(const s of [1,-1]){
    const Lp=RR2(s*.856,s*.93,Y(.858),Y(1.342),.012),inRev=(z,y)=>y>Y(1.012)&&y<Y(1.108);
    hdLampUnit(out,'R',Lp,cuts,{deep:.07,k:.9,wall:HC.GB,back:()=>HC.REFLC,bulge:.004,cell:.005,lens:(z,y)=>inRev(z,y)?HC.LENSR:HC.REDL,
      inside:o=>{
        /* the black dividers either side of the reversing window */
        for(const y of [1.01,1.11]){const p=[];for(let z=.86;z<=.9261;z+=.008)p.push([s*z,Y(y)]);hdTrim(o,'R',p,.006,.06,HC.GB,false,50,-.065);}
        /* the reflector's ribs in the red, and the bulbs */
        hdPart(o,mb=>{for(const [y0,y1] of [[.872,1.0],[1.122,1.33]])for(let y=y0+.012;y<y1;y+=.016){const a=hdS('R',s*.864,Y(y),-.052),b=hdS('R',s*.922,Y(y),-.052);hdCyl(mb,a,b,.0025,.0025,6,HC.REFLC,false);}},30);
        hdPart(o,mb=>{for(const y of [.935,1.18,1.27])ball(mb,hdS('R',s*.893,Y(y),-.045),.0075,14,HC.BULB);ball(mb,hdS('R',s*.893,Y(1.06),-.045),.0075,12,HC.BULB);},50);
      }});
    /* the black housing round the lamp, proud of the body */
    hdTrim(out,'R',hdResample(RR2(s*.851,s*.934,Y(.852),Y(1.348),.016),.006),.01,.005,HC.GB,true,50);
  }
  /* ---------- the tailgate: the shut gaps cut in (both sides and the bottom), the handle ---------- */
  {const gap=(P)=>{for(const c of cuts)hdCut(c,'R',P,.02);hdRecess(out,'R',P,.014,.7,HC.GB,()=>HC.GB,2);};
    gap(RR2(-.843,.843,Y(.717),Y(.723),.001));for(const s of [1,-1])gap(RR2(s*.837,s*.843,Y(.723),Y(1.416),.001));}
  {const P=RR2(-.14,.14,Y(1.16),Y(1.26),.02);for(const c of cuts)hdCut(c,'R',P);hdRecess(out,'R',P,.038,.92,HC.PLASTIC,()=>HC.GB,5);
    hdPart(out,mb=>{hdRBox(mb,hdS('R',0,Y(1.205),-.018),[.012,.022,.115],.008,HC.PLASTIC,3);},40);
    hdRevAt(out,'R',hdS('R',.11,Y(1.235),-.004),[[.011,0],[.011,.003],[.008,.0045],[.002,.0045],[0,.004]],MM.CHROME,24);}
  pkBumperR(out,car);
  /* ---------- the third brake lamp and the cargo lamps, on the cab's roof edge ---------- */
  {const yc=Y(1.846),c=hdS('R',0,yc,0);
    hdPart(out,mb=>{hdRBox(mb,[c[0]+.012,yc,0],[.026,.024,.215],.012,HC.GB,4);},40);
    hdPart(out,mb=>{hdRBox(mb,[c[0]-.0145,yc+.002,0],[.002,.012,.15],.002,HC.REDL,2);},40);
    for(const z of [-.185,.185])hdPart(out,mb=>{hdRBox(mb,[c[0]-.0145,yc+.002,z],[.002,.012,.022],.002,HC.LENS,2);},40);}
}
/* the step bumper (in place of REARS.pickup's boxes): lofted along its plan, holes for the plate */
function pkBumperR(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,X=K.X,xr=X(D.L)-.09,BL=SV(lin('#151517'),SM.PAINTED),RUB=SV([.016,.016,.017],MAT.RUBBER);
  const half=[];for(let z=0;z<=.84;z+=.02)half.push([xr,z]);const rc=.07;for(let k=1;k<=12;k++){const a=k/12*PI/2;half.push([xr+rc-Math.cos(a)*rc,.84+Math.sin(a)*rc]);}
  half.push([xr+rc+.06,.91]);
  const plan=[...half.slice(1).reverse().map(([x,z])=>[x,-z]),...half];
  const st=plan.map((p,i)=>{const a=plan[Math.max(0,i-1)],b=plan[Math.min(plan.length-1,i+1)],tx=b[0]-a[0],tz=b[1]-a[1],l=Math.hypot(tx,tz)||1;let n=[-tz/l,tx/l];
    if(n[0]*(xr+1-p[0])+n[1]*(0-p[1])<0)n=[-n[0],-n[1]];return {p,n};});
  /* the section, from the step's front edge over the top, down the face, under it (q: how far forward from the plan) */
  const sec=[[.125,Y(.746)],[.05,Y(.749)],[.016,Y(.747)],[.004,Y(.741)],[0,Y(.728)],[0,Y(.705)],[0,Y(.66)],[0,Y(.62)],[0,Y(.582)],[.003,Y(.566)],[.012,Y(.556)],[.03,Y(.552)],[.13,Y(.55)]];
  const P=(i,j)=>{const s=st[i],[q,y]=sec[j];return [s.p[0]+s.n[0]*q,y,s.p[1]+s.n[1]*q];};
  const plate=(z,y)=>Math.abs(z)<.168&&y>Y(.582)&&y<Y(.705);
  hdPart(out,mb=>{for(let i=0;i<st.length-1;i++)for(let j=0;j<sec.length-1;j++){const a=P(i,j),b=P(i+1,j),c=P(i+1,j+1),d=P(i,j+1);if(plate((a[2]+c[2])/2,(a[1]+c[1])/2))continue;mb.quad(a,b,c,d,BL[0],BL[1],BL[2]);}
    for(const i of [0,st.length-1])for(let j=1;j<sec.length-1;j++)mb.tri(P(i,0),P(i,j),P(i,j+1),BL[0],BL[1],BL[2]);},38);
  /* the step's rubber pad, ribbed across */
  hdPart(out,mb=>{const y0=Y(.7485);for(let z=-.8;z<.8;z+=.018){const z1=Math.min(z+.012,.8);
      hdRBox(mb,[xr+.06,y0+.003,(z+z1)/2],[.045,.003,(z1-z)/2],.0015,RUB,1);}
    hdRBox(mb,[xr+.06,y0+.0005,0],[.05,.001,.81],.001,RUB,1);},30);
  /* the plate in its recess, its lamps over it, a plain raised border */
  {const rim=hdResample(RR2(-.168,.168,Y(.582),Y(.705),.012),.008),B=rim.map(([z,y])=>[xr+.022,y,z]);
    hdPart(out,mb=>{hdLoft(mb,[rim.map(([z,y])=>[xr-.0005,y,z]),B],BL,true);hdCap(mb,B,BL,false);},30);
    const pl=hdResample(RR2(-.152,.152,Y(.588),Y(.698),.008),.01);
    hdPart(out,mb=>{const F=pl.map(([z,y])=>[xr+.012,y,z]),Bk=pl.map(([z,y])=>[xr+.018,y,z]);hdCap(mb,F,SV([1,1,1],MAT.PLATE),true);hdLoft(mb,[F,Bk],SV([1,1,1],MAT.PLATE),true);},20);
    hdPart(out,mb=>{const r=hdResample(RR2(-.146,.146,Y(.594),Y(.692),.006),.01);hdTube(mb,r.map(([z,y])=>[xr+.0105,y,z]).concat([[xr+.0105,r[0][1],r[0][0]]]),.0018,6,SV([.05,.07,.18],MAT.COL),false,false);},40);
    for(const z of [-.11,.11])hdPart(out,mb=>{hdCyl(mb,[xr+.012,Y(.682),z],[xr+.008,Y(.682),z],.006,.0055,10,MM.CHROME);},40);
    for(const z of [-.07,.07])hdPart(out,mb=>{hdRBox(mb,[xr+.004,Y(.717),z],[.004,.006,.024],.003,HC.LENS,2);},40);}
  /* the hitch receiver: a square tube out under the middle, its collar, the pin across it and the clip */
  {const y=Y(.5),x0=xr+.12,x1=xr-.035,ST=SV(lin('#121213'),SM.PAINTED);
    hdPart(out,mb=>{const sq=hdRRect(.03,.03,.005,3),ring=x=>sq.map(([a,b])=>[x,y+b,a]),inner=hdRRect(.0254,.0254,.003,3),ri=x=>inner.map(([a,b])=>[x,y+b,a]);
      hdLoft(mb,[ring(x0),ring(x1)],ST,true);hdLoft(mb,[ring(x1),ri(x1)],ST,true);hdLoft(mb,[ri(x1),ri(x1+.08)],HC.GB,true);hdCap(mb,ri(x1+.08),HC.GB,false);
      const col=hdRRect(.036,.036,.006,3);hdLoft(mb,[col.map(([a,b])=>[x1+.006,y+b,a]),col.map(([a,b])=>[x1+.026,y+b,a])],ST,true);},40);
    hdPart(out,mb=>{hdCyl(mb,[x1+.045,y,-.048],[x1+.045,y,.05],.0065,.0065,12,MM.CHROME);hdCyl(mb,[x1+.045,y,-.048],[x1+.045,y,-.052],.011,.011,12,MM.CHROME);
      const clip=[];for(let k=0;k<=14;k++){const a=k/14*PI*1.6-PI*.3;clip.push([x1+.045+Math.cos(a)*.018,y-.012+Math.sin(a)*.03,.056]);}hdTube(mb,clip,.0022,6,MM.CHROME,false,true);},40);}
}

;
/* =====================================================================================
   THE PICKUP'S BED. The game's bed is its body's own section (21_suv secKeys, a bed): the rail's inner edge, a
   straight inner wall and a flat lined floor at 1.0 m. Its shape is kept; on it:
   - the floor's corrugations, ten raised ribs from the front wall to the tailgate, in black bed-liner;
   - black caps on the rail tops, rounded over the outer edge, with the stake pockets in them;
   - four tie-down hooks in cups in the inner walls;
   - the tailgate's inner face pressed into ribs, its latch strikers and support cables;
   - two cargo hooks on the front wall.
   ===================================================================================== */
function pkBed(out,car){
  const K=HDK,D=K.D,dy=K.dy,Y=y=>y+dy,X=K.X,L=D.L,u0=D.B.bed+.03,u1=L-.012,BL=HC.BEDLINER;
  const k=u=>secKeys(D,u),floorY=u=>k(u).yT,wallZ=u=>k(u).P[10][0],railZ=u=>k(u).P[8][0];
  /* ---------- the floor's ribs ---------- */
  {const zf=k((u0+u1)/2).P[11][0]-.03,n=10;
    for(let i=0;i<n;i++){const z=-zf+2*zf*(i+.5)/n,path=[];for(let u=u0+.04;u<=u1-.02+1e-6;u+=.1)path.push([X(u),floorY(u)-.002,z]);path.push([X(u1-.02),floorY(u1-.02)-.002,z]);
      hdPart(out,mb=>{const sec=[[-.028,0],[-.024,.006],[-.016,.011],[.016,.011],[.024,.006],[.028,0]].map(([a,b])=>[a,b]);hdSweep(mb,path,sec,BL,[0,1,0],false,true);},40);}}
  /* ---------- the rail caps, the stake pockets ---------- */
  for(const s of [1,-1]){const path=[];for(let u=D.B.bed-.02;u<=L-.005+1e-6;u+=.05)path.push(u);path.push(L-.005);
    hdPart(out,mb=>{const rings=path.map(u=>{const kk=k(u),zi=kk.P[8][0]-.006,zo=kk.P[7][0]+.012,yt=kk.P[8][1]+.012,yb=kk.P[7][1]-.014;
        return [[zi,kk.P[8][1]-.012],[zi-.002,yt-.004],[zi+.004,yt],[zo-.012,yt],[zo-.003,yt-.005],[zo+.001,yt-.016],[zo,yb]].map(([z,y])=>[X(u),y,s*z]);});
      hdLoft(mb,rings,HC.PLASTIC,false,s<0);for(const i of [0,rings.length-1]){const r=rings[i];for(let j=1;j<r.length-1;j++)mb.tri(r[0],r[j],r[j+1],HC.PLASTIC[0],0,HC.PLASTIC[2]);}},40);
    for(const u of [D.B.bed+.25,L-.35]){const kk=k(u),zc=(kk.P[8][0]+kk.P[7][0])/2,yt=kk.P[8][1]+.0125;
      hdPart(out,mb=>{hdRBox(mb,[X(u),yt+.0005,s*zc],[.03,.0012,.016],.002,HC.GB,1);},30);}}
  /* ---------- the tie-down hooks ---------- */
  for(const s of [1,-1])for(const u of [D.B.bed+.12,L-.2]){const z=wallZ(u),y=Y(1.2);
    hdPart(out,mb=>{hdRBox(mb,[X(u),y,s*(z-.004)],[.035,.035,.006],.008,HC.GB,3);},40);
    hdPart(out,mb=>{const ring=[];for(let i=0;i<=20;i++){const a=PI*.15+i/20*PI*1.7;ring.push([X(u)+Math.cos(a)*.02,y-.008+Math.sin(a)*-.02,s*(z-.014)]);}hdTube(mb,ring,.004,8,MM.CHROME,false,true);
      hdCyl(mb,[X(u)-.024,y+.012,s*(z-.008)],[X(u)-.024,y+.012,s*(z-.02)],.006,.006,8,MM.CHROME);hdCyl(mb,[X(u)+.024,y+.012,s*(z-.008)],[X(u)+.024,y+.012,s*(z-.02)],.006,.006,8,MM.CHROME);},40);}
  /* ---------- the tailgate's inner face: three pressed ribs, the latch strikers, the cables ---------- */
  {const x=X(L)+.002,zw=wallZ(L-.05)-.06;
    for(const y of [1.12,1.22,1.32])hdPart(out,mb=>{const path=[];for(let z=-zw;z<=zw+1e-6;z+=.05)path.push([x,Y(y),z]);hdSweep(mb,path,[[0,-.018],[-.004,-.012],[-.006,0],[-.004,.012],[0,.018]],SV([1,1,1],MAT.PAINT),[0,1,0],false,true);},40);
    for(const s of [1,-1]){const z=s*(wallZ(L-.03)-.004),y=Y(1.36);
      hdPart(out,mb=>{const U=[];for(let i=0;i<=10;i++){const a=i/10*PI;U.push([X(L-.02)+Math.cos(a)*.012,y,z-s*Math.sin(a)*.012]);}hdTube(mb,U,.0045,8,MM.CHROME,false,true);},40);
      hdPart(out,mb=>{hdTube(mb,[[X(L-.06),Y(1.33),z-s*.004],[X(L-.03),Y(1.2),z-s*.006],[X(L-.01),Y(1.08),z-s*.008]],.004,8,HC.GB,false,true);},40);}}
  /* ---------- the cargo hooks on the front wall ---------- */
  for(const s of [1,-1]){const u=D.B.bed+.008,y=Y(1.3),z=s*.55;
    hdPart(out,mb=>{hdRBox(mb,[X(u)-.006,y,z],[.006,.03,.04],.008,HC.GB,2);const h=[];for(let i=0;i<=12;i++){const a=i/12*PI;h.push([X(u)-.012-Math.sin(a)*.025,y+Math.cos(a)*.022,z]);}hdTube(mb,h,.004,8,MM.CHROME,false,true);},40);}
}

;
/* =====================================================================================
   THE PICKUP'S CABIN (79_cabin hdCabinGen, the SUV Studio's way): a full-size crew cab in its dealer's off-road trim,
   all in dark grey. A tall truck dash with a deep hood over six dials (the speedometer and tachometer, four small
   ones), four vents, the radio and the climate knobs, the four-wheel-drive knob by the light switch; a four-spoke
   wheel with a big hub, the automatic's lever on the column; two buckets with a big console between them (lid, cup
   holders); a three-seat bench behind; four door panels with power-window switches, map pockets and speakers; the
   cab's back wall in vinyl under the rear window.
   ===================================================================================== */
function pkCabin(out,car){
  const D=HDK.D,G=D.G,pil=G.pillars.map(p=>p[0]);
  hdCabinGen(out,car,{floorY:.64+D.dy,uEnd:G.rr-.06,headEnd:G.rr-.03,doors:4,armY:.3,dashDepth:.5,dashTop:D.belt(G.cowl+.5)-.055,hoodH:.065,
    dials:[[-.085,.052,0],[.085,.052,0],[-.185,.024,.022],[-.185,.024,-.032],[.185,.024,.022],[.185,.024,-.032]],clusterW:.235,vents:[-.62,-.14,.14,.62],
    wheelU:.15,wheelDrop:.1,wheelR:.2,spokes:[PI*.06,PI*.94,-PI*.36,-PI*.64],hub:[.085,.1,.034],shifter:'column',fourKnob:1,console:'big',consoleBack:.32,
    seatF:pil[0]+.1,seatY:.3,seatZ:.4,seatW:.53,bolster:1,rear:'bench',seatR:G.rr-.24,rearW:1.5,back:'cab',tunnel:.08,toe:.22,tunnelEnd:pil[0]+.3,
    col:{dash:'#262628',dashTop:'#1c1c1d',vinyl:'#2c2c2e',insert:'#3e3e41',head:'#706d68',carpet:'#252526',seat:'#414144',seatSide:'#333336'}});
}

;
/* =====================================================================================
   THE PICKUP'S BOLT-ONS: the mirrors, door handles and wipers are the shared ones (76_trim, 79_bits, the SUV's way),
   in the build's black; here, in place of EXTRAS.steps' boxes, the running boards, and the fuel door cut in for real.
   - Running boards: a black moulding between the arches, rounded over its outer edge, a ribbed rubber tread along the
     top, end caps tapering down; three steel brackets a side from under the rocker.
   - The fuel door: the game's painted outline taken off; the door cut out of the bed side, a dark gap round it and
     the door itself flush in it.
   ===================================================================================== */
function pkSteps(out,car){
  const K=HDK,D=K.D,X=K.X,u0=D.uFa+D.arch.a+.06,u1=D.uRa-D.archB.a-.06,um=(u0+u1)/2,y=D.sill(um)-.05,z=D.plan(um)+.07,BO=HC.PLASTIC,RUB=SV([.016,.016,.017],MAT.RUBBER);
  for(const s of [1,-1]){
    /* the board: a section swept along it, its ends tapering in */
    const n=40,path=[];for(let i=0;i<=n;i++)path.push(u0+(u1-u0)*i/n);
    const sec=t=>{const e=sm01(Math.min(t,1-t)/.04),w=.08,h=.022*(.55+.45*e);return [[-w,-h],[-w,h*.6],[-w+.01,h],[w-.02,h],[w-.004,h*.7],[w,0],[w-.006,-h*.8],[w-.02,-h],[-w+.01,-h]];};
    hdPart(out,mb=>{const rings=path.map((u,i)=>sec(i/n).map(([a,b])=>[X(u),y+b,s*(z+a)]));hdLoft(mb,rings,BO,true,s<0);
      for(const i of [0,rings.length-1])hdCap(mb,rings[i],BO,(i===0)!==(s<0));},40);
    /* the rubber tread on top: ribs along it */
    hdPart(out,mb=>{for(let k=0;k<6;k++){const a=-.062+k*.022;mb.quad([X(u0+.06),y+.0225,s*(z+a)],[X(u1-.06),y+.0225,s*(z+a)],[X(u1-.06),y+.0225,s*(z+a+.004)],[X(u0+.06),y+.0225,s*(z+a+.004)],RUB[0],0,RUB[2]);
        hdRBox(mb,[X(um),y+.0245,s*(z+a+.011)],[(u1-u0)/2-.07,.0025,.006],.002,RUB,1);}},30);
    /* the brackets: a steel arm from under the rocker out under the board */
    for(const u of [u0+.25,um,u1-.25])hdPart(out,mb=>{const zi=D.plan(u)*.82,yr=D.sill(u)+.01;
      hdTube(mb,[[X(u),yr,s*zi],[X(u),yr-.03,s*(zi+.05)],[X(u),y-.02,s*(z-.04)]],.012,8,HC.CAST,false,true);
      hdRBox(mb,[X(u),y-.024,s*(z-.02)],[.03,.004,.05],.003,HC.CAST,2);for(const du of [-.018,.018])hdCyl(mb,[X(u+du),yr+.004,s*zi],[X(u+du),yr-.012,s*zi],.007,.007,6,HC.BOLT);},40);
  }
}
function pkFuel(out,car){hdFuel(out,car);}

