        const r=[];for(let k=0;k<=20;k++){const a=k/20*TAU;r.push([p[0]+.018+Math.cos(a)*.008,p[1]+.004,p[2]+Math.sin(a)*.008]);}hdTube(mb,r,.0015,6,MM.CHROME,true,false);
